insert into public.card_lore(card_id,card_name,ability_title,ability_text,art_url,faction,power,badge_key) values
('soldado-esparta','Soldado de Esparta','FORMAÇÃO ESPARTANA','Cada outro Soldado de Esparta aliado na mesma fileira dobra o poder desta carta. O efeito é recíproco e acumulativo.','assets/cards-remake/soldado-esparta.webp','Grécia',3,'greece'),
('athena','Athena','FORMAÇÃO FALANGE','Todas as outras cartas na mesma fileira de Athena ganham +2 pontos de poder cada.','assets/cards-remake/athena.webp','Grécia',4,'greece'),
('lobo-alfa','Lobisomem Alfa','UIVO DE ALFA','Recebe +2 de poder por Lobisomem Beta aliado na mesma fileira.','assets/cards-remake/lobo-alfa.webp','Monstros',4,'monster'),
('guardiao-nordico','Guardião Nórdico','VONTADE DO NORTE','Cada outro Guardião Nórdico aliado na mesma fileira dobra seu poder. O efeito é recíproco e acumulativo.','assets/cards-remake/guardiao-nordico.webp','Nórdicos',2,'norse'),
('medusa','Medusa','VIRE PEDRA','Ao entrar, os jogadores inimigos perdem seu próximo turno. Em duplas, afeta ambos os adversários, mesmo com Heimdall.','assets/cards-remake/medusa.webp','Grécia',4,'greece'),
('poseidon','Poseidon','DEUS DO MAR','Ao entrar, o tsunami reduz em 2 o poder das unidades inimigas presentes na fileira superior. Novas entradas não são afetadas.','assets/cards-remake/poseidon.webp','Grécia',7,'greece'),
('zeus','Zeus','SENHOR DOS CÉUS','Ao entrar, destrói até duas unidades inimigas aleatórias que possam ser afetadas.','assets/cards-remake/zeus.webp','Grécia',8,'greece'),
('hades','Hades','SUBMUNDO RESPONDA','Ao entrar, escolha uma unidade do seu próprio Submundo para retornar na fileira de Hades, ativando sua habilidade de entrada.','assets/cards-remake/hades.webp','Grécia',7,'greece'),
('lobo-omega','Lobisomem Omega','ENCURRALADO','Se o Lobisomem Omega for o único na sua fileira de batalha e o inimigo tiver mais poder que o Omega, seu poder aumenta em 8.','assets/cards-remake/lobo-omega.webp','Monstros',1,'monster'),
('lukyan','Lukyan — Rei da Festa','REI DA FESTA','Enquanto houver outro aliado na mesma fileira, recebe +3 de poder. O bônus é recalculado ao mudar de fileira.','assets/cards-remake/lukyan.webp','Alyns',3,'alyans'),
('anubis','Anúbis','TROCA VELOZ','Ao entrar, envia uma unidade inimiga ao Submundo e pode recuperar uma unidade do próprio Submundo com o mesmo poder atual que a vítima tinha antes de sair.','assets/cards-remake/anubis.webp','Egípcios',5,'egypt'),
('odin','Odin','SABEDORIA DE YGGDRASIL','No início do próximo turno do dono, observe a carta do topo do seu baralho. Você pode descartá-la para ganhar +2 na soma da rodada ou mantê-la no topo.','assets/cards-remake/odin.webp','Nórdicos',8,'norse'),
('lukyan-rei-de-todos','Lukyan — Rei de Todos','REI DE TODOS','COM EXCALIBUR, SEU PODER GANHA 1 PONTO POR CADA OUTRO ALIADO EM TODO O SEU CAMPO.','assets/cards-remake/lukyan-rei-de-todos.webp','Alyns',6,'alyans'),
('minotauro','Minotauro','FÚRIA DO LABIRINTO','Ao entrar em campo, se estiver sozinho em sua fileira de batalha, ganha +3 pontos de poder.','assets/cards-remake/minotauro.webp','Grécia',3,'greece'),
('apolo','Apolo','BENÇÃO DO SOL','Enquanto Apolo estiver em campo, dobra o poder de todas as cartas aliadas na sua fileira, incluindo ele próprio e as que entrarem depois.','assets/cards-remake/apolo.webp','Grécia',6,'greece'),
('ra','Rá','LUZ DA CRIAÇÃO','No fim de cada turno do dono, concede +1 de poder a cada egípcio aliado na mesma fileira. Os bônus são limpos no fim do Round.','assets/cards-remake/ra.webp','Egípcios',8,'egypt'),
('ragnar','Ragnar','INVASORES DE KATGAT','Ao entrar em campo, move uma carta aliada de baixo poder de outra fileira para a mesma fileira de Ragnar, unindo as forças.','assets/cards-remake/ragnar.webp','Nórdicos',3,'norse'),
('afrodite','Afrodite','MEU AMADO TRAIDOR','Ao entrar em campo, o invocador pode escolher uma carta inimiga em campo para roubar, desde que ela tenha menos de 5 de poder.','assets/cards-remake/afrodite.webp','Grécia',5,'greece'),
('aquiles','Aquiles','A FÚRIA DE MIRMIDÃO','Ao entrar em campo, ganha +1 de poder para cada soldado grego ou herói aliado em sua fileira.','assets/cards-remake/aquiles.webp','Grécia',3,'greece'),
('seth','Seth','TROVOADA DO CAOS','Ao entrar em campo, escolhe uma fileira e troca os valores de poder de todas as cartas nela, aliadas e inimigas, de forma aleatória entre elas.','assets/cards-remake/seth.webp','Egípcios',4,'egypt'),
('osiris','Osíris','JUSTIÇA CÍCLICA','Ao ser destruído e enviado para o cemitério, dobra o poder de outra carta aliada aleatória em campo.','assets/cards-remake/osiris.webp','Egípcios',6,'egypt'),
('thor','Thor','MARTELADA DE MJÖLNIR','Ao entrar em campo, escolhe a carta inimiga de maior poder e a envia para o Submundo.','assets/cards-remake/thor.webp','Nórdicos',6,'norse'),
('artemis','Ártemis','TIRO PRECISO','Ao entrar em campo, elimina duas cartas Monstros de cada lado.','assets/cards-remake/artemis.webp','Grécia',5,'greece'),
('sobek','Sobek','INUNDAÇÃO FERTILIZANTE','Ao entrar em campo, se houver outra carta aliada na mesma fileira, ganha +2 de poder adicional.','assets/cards-remake/sobek.webp','Egípcios',2,'egypt'),
('ares','Ares','DEUS DA GUERRA','Ao entrar, concede +2 aos espartanos e a Leônidas e +1 aos demais gregos aliados na mesma fileira.','assets/cards-remake/ares.webp','Grécia',5,'greece'),
('beowulf','Beowulf','CORAGEM DE GEAT','Ao entrar em campo, se houver alguma carta da facção Monstros na mesa, ganha +3 pontos de poder adicional.','assets/cards-remake/beowulf.webp','Nórdicos',3,'norse'),
('heimdall','Heimdall','VIGÍLIA DE BIFRÖST','Enquanto ativo, protege a própria fileira de efeitos inimigos, incluindo destruição, roubo, movimento, transformação e alterações de poder. Medusa afeta o jogador e não é bloqueada.','assets/cards-remake/heimdall.webp','Nórdicos',3,'norse'),
('dionisio','Dionísio','FESTIVAL DO VINHO','Ao entrar, silencia efeitos pelas próximas 3 jogadas da partida, contando aliados e adversários. Fileiras inimigas protegidas por Heimdall resistem ao silêncio.','assets/cards-remake/dionisio.webp','Grécia',4,'greece'),
('butter','Butter','CLEPTOMANÍACO','Ao entrar, rouba uma carta aleatória da mão inimiga. Sem cartas na mão, rouba do baralho; se também estiver vazio, do Submundo inimigo.','assets/cards-remake/butter.webp','Alyns',4,'alyans'),
('hefesto','Hefestos','MELHORIA ARTEFATUAL','Ao entrar em campo, aumenta em +3 os pontos de poder de um personagem com carta de equipamento.','assets/cards-remake/hefesto.webp','Grécia',4,'greece'),
('hercules','Hércules','OS DOZE TRABALHOS','No fim de cada turno do dono, ganha +1 de poder, até 12 de progresso. Todo progresso é zerado ao trocar de Round.','assets/cards-remake/hercules.webp','Grécia',4,'greece'),
('hermes','Hermes','TROCA VELOZ','Ao entrar em campo, você pode mover outra carta sua de uma fileira para outra, reorganizando sua pontuação.','assets/cards-remake/hermes.webp','Grécia',3,'greece'),
('horus','Hórus','OLHO DE HÓRUS','Ao entrar, somente o dono vê até duas cartas aleatórias da mão adversária, inclusive em duplas.','assets/cards-remake/horus.webp','Egípcios',4,'egypt'),
('lobo-beta','Lobisomem Beta','UIVO DO BETINHA','Ao entrar em campo, chama os outros Betas que estiverem na mão do invocador para o campo.','assets/cards-remake/lobo-beta.webp','Monstros',2,'monster'),
('isis','Ísis','RESSURREIÇÃO DE OSÍRIS','Ao entrar em campo, escolha uma carta com 2 ou menos de poder do seu próprio Submundo para retornar ao campo na fileira de Ísis.','assets/cards-remake/isis.webp','Egípcios',4,'egypt'),
('mulher','Mulher','AINDA SOU ALFA','Cada Homem aliado na mesma fileira dobra seu poder. No Eclipse Lunar, Mulher da facção Monstros vira Lobisomem Alfa; fora do Lunar, recupera sua forma original.','assets/cards-remake/mulher.webp','Monstros',2,'monster'),
('homem','Homem','JUNTOS SOMOS FORTES','Cada outro Homem aliado na mesma fileira dobra seu poder. No Eclipse Lunar, Homem da facção Monstros vira Lobisomem Beta; fora do Lunar, recupera sua forma original.','assets/cards-remake/homem.webp','Monstros',1,'monster'),
('loki','Loki','ILUSÃO TRAIÇOEIRA','Ao entrar, copia a habilidade, a identidade e o poder completo de um inimigo, incluindo bônus e equipamentos. A cópia termina ao sair do campo ou encerrar o Round.','assets/cards-remake/loki.webp','Nórdicos',3,'norse'),
('japonesa-amaterasu','Amaterasu','AURORA CELESTIAL','Enquanto estiver em campo, as outras unidades Japonesas aliadas em sua fileira recebem +2 de poder. Não acumula com outra Amaterasu.','assets/cards-remake/japonesa-amaterasu.webp','Japonesa',5,'japanese'),
('chinesa-ao-guang','Ao Guang','TRIBUTO DO MAR','Ao entrar, devolva um equipamento inimigo à mão de seu dono. Se fizer isso, compre 1 carta.','assets/cards-remake/chinesa-ao-guang.webp','Chinesa',4,'chinese'),
('brasil-boitata','Boitatá','FOGO QUE PROTEGE','Uma vez por Round, enquanto Boitatá estiver em campo com a habilidade ativa, impeça a primeira destruição causada por um efeito inimigo contra outra unidade Brasil aliada de sua fileira.','assets/cards-remake/brasil-boitata.webp','Brasil',6,'brasil'),
('brasil-boto','Boto Encantado','BAILE DO ENCANTADO','Ao entrar, você pode devolver outra unidade Brasil aliada de sua fileira para a sua mão. Se ela voltar para a mão, Boto recebe +2 de poder até o fim do Round. Retornar à mão não conta como destruição.','assets/cards-remake/brasil-boto.webp','Brasil',5,'brasil'),
('celtas-brigid','Brigid','CHAMA DE RENOVAÇÃO','Ao entrar, remova as reduções de poder de outra unidade aliada em sua fileira e conceda +2 a ela até o fim do Round.','assets/cards-remake/celtas-brigid.webp','Celtas',4,'celtic'),
('brasil-caipora','Caipora','PACTO DA MATA','Enquanto Caipora estiver em campo com a habilidade ativa, as outras unidades Brasil aliadas de sua fileira recebem +1 de poder, incluindo as que chegarem depois. O bônus termina ao sair da fileira ou quando a habilidade deixar de atuar.','assets/cards-remake/brasil-caipora.webp','Brasil',4,'brasil'),
('asteca-chalchiuhtlicue','Chalchiuhtlicue','ÁGUAS DO RENASCIMENTO','Ao entrar, recupere uma unidade Asteca de poder base até 4 do seu submundo para sua mão.','assets/cards-remake/asteca-chalchiuhtlicue.webp','Asteca',4,'aztec'),
('chinesa-change','Chang''e','REFÚGIO NA LUA','Ao entrar, escolha outra unidade aliada nesta fileira. Até o início do seu próximo turno, ela não pode ser destruída ou roubada por efeitos inimigos.','assets/cards-remake/chinesa-change.webp','Chinesa',4,'chinese'),
('asteca-coatlicue','Coatlicue','VENTRE DA TERRA','Enquanto estiver em campo, Coatlicue recebe +1 de poder por cada 2 unidades no seu submundo.','assets/cards-remake/asteca-coatlicue.webp','Asteca',5,'aztec'),
('brasil-cuca','Cuca','NÉVOA DOS PESADELOS','Ao entrar, silencie a habilidade de uma unidade inimiga na fileira oposta pelas próximas 2 jogadas da partida, contando aliados e inimigos. A contagem começa após esta jogada.','assets/cards-remake/brasil-cuca.webp','Brasil',4,'brasil'),
('brasil-curupira','Curupira','CAMINHOS INVERTIDOS','Enquanto Curupira estiver em campo com a habilidade ativa, efeitos inimigos não podem mover as unidades aliadas de sua fileira.','assets/cards-remake/brasil-curupira.webp','Brasil',5,'brasil'),
('celtas-cu-chulainn','Cú Chulainn','FÚRIA DO CÃO','Na primeira vez em cada Round que outra unidade aliada de sua fileira for destruída, Cú Chulainn recebe +4 até o fim do Round.','assets/cards-remake/celtas-cu-chulainn.webp','Celtas',7,'celtic'),
('celtas-dagda','Dagda','CALDEIRÃO DA ABUNDÂNCIA','Ao entrar, ressuscite uma unidade Celta de poder base até 3 do seu submundo nesta fileira, sem ativar sua habilidade de entrada.','assets/cards-remake/celtas-dagda.webp','Celtas',4,'celtic'),
('celtas-dama-do-lago','Dama do Lago','DÁDIVA DO LAGO','Ao entrar, recupere um equipamento do seu submundo para sua mão.','assets/cards-remake/celtas-dama-do-lago.webp','Celtas',4,'celtic'),
('hindu-durga','Durga','MURALHA DA DEUSA','Enquanto Durga estiver em campo, as outras unidades Hindus aliadas em sua fileira não podem ser destruídas por habilidades inimigas.','assets/cards-remake/hindu-durga.webp','Hindu',7,'hindu'),
('mesopotamica-enki','Enki','ÁGUAS DA SABEDORIA','Ao entrar, recupere uma carta de Local ou Terreno do seu submundo para sua mão.','assets/cards-remake/mesopotamica-enki.webp','Mesopotâmica',4,'mesopotamian'),
('mesopotamica-enlil','Enlil','SOPRO DOS IMPÉRIOS','Ao entrar, mova outra unidade aliada para uma fileira aliada com espaço. Ela recebe +2 até o fim do Round se for Mesopotâmica.','assets/cards-remake/mesopotamica-enlil.webp','Mesopotâmica',6,'mesopotamian'),
('mesopotamica-ereshkigal','Ereshkigal','TRONO DO SUBMUNDO','Enquanto Ereshkigal estiver em campo, unidades no submundo inimigo não podem ser ressuscitadas na fileira oposta.','assets/cards-remake/mesopotamica-ereshkigal.webp','Mesopotâmica',7,'mesopotamian'),
('chinesa-erlang-shen','Erlang Shen','OLHO DA VERDADE','Ao entrar, remova os bônus positivos de poder de uma unidade inimiga à sua escolha. Equipamentos permanecem e deixam de conceder poder neste Round.','assets/cards-remake/chinesa-erlang-shen.webp','Chinesa',6,'chinese'),
('chinesa-fuxi','Fuxi','OITO TRIGRAMAS','Ao entrar, veja as 3 primeiras cartas do seu deck e devolva-as ao topo na ordem que quiser. Compre 1 carta.','assets/cards-remake/chinesa-fuxi.webp','Chinesa',4,'chinese'),
('japonesa-fujin','Fūjin','VENTOS ERRANTES','Ao entrar, mova outra unidade aliada para uma fileira aliada à sua escolha que tenha espaço.','assets/cards-remake/japonesa-fujin.webp','Japonesa',4,'japanese'),
('hindu-ganesha','Ganesha','ABRIDOR DE CAMINHOS','Ao entrar, remova o silêncio de outra unidade aliada. Se nenhuma estiver silenciada, compre 1 carta.','assets/cards-remake/hindu-ganesha.webp','Hindu',4,'hindu'),
('chinesa-guanyin','Guanyin','COMPAIXÃO INFINITA','Ao entrar, recupere para sua mão uma unidade de poder base até 4 do seu submundo.','assets/cards-remake/chinesa-guanyin.webp','Chinesa',4,'chinese'),
('japonesa-hachiman','Hachiman','ESTANDARTE DE GUERRA','Ao fim de cada turno do seu dono, Hachiman recebe +1 de poder até o fim do Round se houver outra unidade aliada nesta fileira.','assets/cards-remake/japonesa-hachiman.webp','Japonesa',6,'japanese'),
('hindu-hanuman','Hanuman','SALTO DEVOTO','Ao entrar, você pode mover Hanuman para outra fileira aliada com espaço. Se mover, ele recebe +2 até o fim do Round.','assets/cards-remake/hindu-hanuman.webp','Hindu',6,'hindu'),
('chinesa-hou-yi','Hou Yi','FLECHA DOS NOVE SÓIS','Ao entrar, uma unidade inimiga à sua escolha perde 4 de poder até o fim do Round.','assets/cards-remake/chinesa-hou-yi.webp','Chinesa',6,'chinese'),
('asteca-huitzilopochtli','Huitzilopochtli','MARCHA DO SOL','Ao entrar, você pode destruir outra unidade aliada desta fileira. Se fizer isso, as demais unidades aliadas já nela recebem +2 até o fim do Round.','assets/cards-remake/asteca-huitzilopochtli.webp','Asteca',5,'aztec'),
('brasil-iara','Iara','CANTO DAS ÁGUAS','Ao entrar, escolha uma unidade inimiga com até 5 de poder atual na fileira oposta. Traga-a para a fileira de Iara, se houver espaço. A habilidade de entrada da unidade não é ativada.','assets/cards-remake/brasil-iara.webp','Brasil',5,'brasil'),
('chinesa-imperador-jade','Imperador de Jade','MANDATO CELESTIAL','Enquanto estiver em campo, as outras unidades Chinesas aliadas em sua fileira recebem +1 de poder para cada fileira aliada ocupada.','assets/cards-remake/chinesa-imperador-jade.webp','Chinesa',8,'chinese'),
('japonesa-inari','Inari','COLHEITA DAS RAPOSAS','Ao entrar, compre 1 carta. Se houver outra unidade Japonesa aliada nesta fileira, Inari recebe +2 até o fim do Round.','assets/cards-remake/japonesa-inari.webp','Japonesa',3,'japanese'),
('hindu-indra','Indra','VAJRA CELESTIAL','Ao entrar, destrua um equipamento inimigo à sua escolha. Se não houver equipamento inimigo, Indra recebe +2 até o fim do Round.','assets/cards-remake/hindu-indra.webp','Hindu',5,'hindu'),
('mesopotamica-ishtar','Ishtar','ESTRELA DA CONQUISTA','Ao entrar, se sua fileira tiver menos poder total que a oposta, roube uma unidade inimiga dela de poder atual até 4 para sua fileira, se houver espaço.','assets/cards-remake/mesopotamica-ishtar.webp','Mesopotâmica',5,'mesopotamian'),
('japonesa-izanagi','Izanagi','SOPRO DA CRIAÇÃO','Ao entrar, ressuscite uma unidade Japonesa de poder base até 4 do seu submundo nesta fileira, sem ativar sua habilidade de entrada.','assets/cards-remake/japonesa-izanagi.webp','Japonesa',5,'japanese'),
('japonesa-izanami','Izanami','PORTÕES DE YOMI','Ao entrar, escolha uma unidade inimiga de poder atual até 5. Destrua-a e dê -2 a Izanami até o fim do Round.','assets/cards-remake/japonesa-izanami.webp','Japonesa',6,'japanese'),
('hindu-kali','Kali','FIM DO CICLO','Ao entrar, escolha outra unidade aliada nesta fileira e destrua-a. Depois, destrua uma unidade inimiga de poder atual até o dela antes da destruição.','assets/cards-remake/hindu-kali.webp','Hindu',7,'hindu'),
('hindu-krishna','Krishna','CANÇÃO DO DEVER','Enquanto Krishna estiver em campo, as outras unidades Hindus aliadas em sua fileira recebem +1 de poder por equipamento nelas, até +3 por unidade.','assets/cards-remake/hindu-krishna.webp','Hindu',5,'hindu'),
('hindu-lakshmi','Lakshmi','FORTUNA FLORESCENTE','Ao entrar, compre 1 carta. Se houver outra unidade Hindu aliada nesta fileira, dê +2 a ela até o fim do Round.','assets/cards-remake/hindu-lakshmi.webp','Hindu',3,'hindu'),
('brasil-lampiao','Lampião','EMBOSCADA DA CAATINGA','Ao entrar, você pode mover outra unidade Brasil aliada para a fileira de Lampião, se houver espaço. Se ela mudar de fileira, recebe +2 de poder até o fim do Round.','assets/cards-remake/brasil-lampiao.webp','Brasil',6,'brasil'),
('celtas-lancelot','Lancelot','CAMPEÃO DO REI','Enquanto houver outra unidade Celta aliada na mesma fileira, Lancelot recebe +3 de poder.','assets/cards-remake/celtas-lancelot.webp','Celtas',4,'celtic'),
('celtas-lugh','Lugh','MESTRE DAS ARTES','Ao entrar, escolha: compre 1 carta ou conceda +3 de poder a outra unidade aliada desta fileira até o fim do Round.','assets/cards-remake/celtas-lugh.webp','Celtas',6,'celtic'),
('brasil-mapinguari','Mapinguari','RUGIDO DA FLORESTA','Enquanto houver pelo menos 2 outras unidades Brasil aliadas em sua fileira, Mapinguari recebe +3 de poder. O bônus é recalculado quando unidades entram, saem ou mudam de fileira.','assets/cards-remake/brasil-mapinguari.webp','Brasil',4,'brasil'),
('mesopotamica-marduk','Marduk','DECRETO DA BABILÔNIA','Ao entrar, destrua uma unidade inimiga de poder atual até 6. Marduk perde 2 de poder até o fim do Round se destruir uma unidade.','assets/cards-remake/mesopotamica-marduk.webp','Mesopotâmica',7,'mesopotamian'),
('celtas-merlin','Merlin','VISÃO DE AVALON','Ao entrar, veja as 3 primeiras cartas do seu deck. Escolha 1 para sua mão e devolva as demais ao fundo, na ordem que quiser.','assets/cards-remake/celtas-merlin.webp','Celtas',3,'celtic'),
('asteca-mictecacihuatl','Mictecacíhuatl','MEMÓRIA DOS MORTOS','Ao entrar, compre 1 carta se seu submundo contiver uma unidade. Se contiver 3 ou mais, Mictecacíhuatl também recebe +2 até o fim do Round.','assets/cards-remake/asteca-mictecacihuatl.webp','Asteca',4,'aztec'),
('asteca-mictlantecuhtli','Mictlantecuhtli','SENHOR DE MICTLAN','Ao entrar, escolha até 2 unidades no submundo inimigo. Elas não podem sair de lá até o fim do Round.','assets/cards-remake/asteca-mictlantecuhtli.webp','Asteca',5,'aztec'),
('celtas-morgana','Morgana','VÉU DA FEITICEIRA','Ao entrar, escolha uma unidade inimiga na fileira oposta. Silencie sua habilidade até o fim do próximo turno do dono dela.','assets/cards-remake/celtas-morgana.webp','Celtas',5,'celtic'),
('celtas-morrigan','Morrigan','PRESSÁGIO DOS CORVOS','Ao entrar, uma unidade inimiga à sua escolha perde 1 de poder por unidade no submundo inimigo, até o fim do Round.','assets/cards-remake/celtas-morrigan.webp','Celtas',5,'celtic'),
('brasil-mula-sem-cabeca','Mula sem Cabeça','GALOPE EM CHAMAS','Ao entrar, reduza em 2 o poder de cada unidade inimiga que já estiver na fileira oposta, até o fim do Round, sem reduzir abaixo de 0. Não afeta unidades que entrarem depois.','assets/cards-remake/brasil-mula-sem-cabeca.webp','Brasil',7,'brasil'),
('mesopotamica-nanna-sin','Nanna - Sîn','CRESCENTE DE UR','Ao fim de cada turno do seu dono, Nanna / Sin recebe +1 de poder até o fim do Round se houver uma carta de Clima em campo.','assets/cards-remake/mesopotamica-nanna-sin.webp','Mesopotâmica',5,'mesopotamian'),
('mesopotamica-nergal','Nergal','SOMBRA DA PESTE','Ao entrar, todas as outras unidades já presentes na fileira de Nergal e na fileira oposta perdem 2 de poder até o fim do Round.','assets/cards-remake/mesopotamica-nergal.webp','Mesopotâmica',6,'mesopotamian'),
('chinesa-nezha','Nezha','RODAS DE FOGO','Ao entrar, mova uma unidade inimiga da fileira oposta para outra fileira inimiga com espaço. Ela perde 2 de poder até o fim do Round.','assets/cards-remake/chinesa-nezha.webp','Chinesa',6,'chinese'),
('mesopotamica-ninurta','Ninurta','CAÇADOR DE MONSTROS','Ao entrar, destrua uma unidade inimiga da facção Monstros com poder atual até 6 na fileira oposta.','assets/cards-remake/mesopotamica-ninurta.webp','Mesopotâmica',7,'mesopotamian'),
('chinesa-nuwa','Nüwa','REMENDO DOS CÉUS','Ao entrar, remova as reduções de poder de até 2 outras unidades aliadas em sua fileira.','assets/cards-remake/chinesa-nuwa.webp','Chinesa',5,'chinese'),
('asteca-quetzalcoatl','Quetzalcóatl','SOPRO DA SERPENTE','Ao entrar, compre 1 carta. Depois, você pode mover outra unidade aliada para uma fileira aliada com espaço.','assets/cards-remake/asteca-quetzalcoatl.webp','Asteca',5,'aztec'),
('japonesa-raijin','Raijin','TAMBORES DO TROVÃO','Ao entrar, escolha até 2 unidades inimigas na fileira oposta. Cada uma perde 2 de poder até o fim do Round.','assets/cards-remake/japonesa-raijin.webp','Japonesa',6,'japanese'),
('rei-arthur','Rei Arthur','JURAMENTO DA TÁVOLA','Enquanto Arthur estiver em campo, as outras unidades Celtas aliadas em sua fileira recebem +1 de poder.','assets/cards-remake/rei-arthur.webp','Celtas',5,'celtic'),
('japonesa-ryujin','Ryūjin','MARÉ DO REI DRAGÃO','Ao entrar, as unidades inimigas já presentes na fileira oposta perdem 2 de poder até o fim do Round.','assets/cards-remake/japonesa-ryujin.webp','Japonesa',8,'japanese'),
('brasil-saci','Saci-Pererê','REDEMOINHO TRAVESSO','Ao entrar, escolha uma unidade inimiga na fileira oposta. Mova-a para outra fileira inimiga à sua escolha, se houver espaço.','assets/cards-remake/brasil-saci.webp','Brasil',3,'brasil'),
('hindu-saraswati','Saraswati','MELODIA DO CONHECIMENTO','Ao entrar, veja as 2 primeiras cartas do seu deck. Adicione 1 à sua mão e coloque a outra no fundo.','assets/cards-remake/hindu-saraswati.webp','Hindu',4,'hindu'),
('hindu-shiva','Shiva','DANÇA DA RENOVAÇÃO','Ao entrar, destrua a outra unidade de menor poder atual em cada lado. Em caso de empate, seu dono escolhe entre as empatadas.','assets/cards-remake/hindu-shiva.webp','Hindu',8,'hindu'),
('chinesa-sun-wukong','Sun Wukong','PELOS DO REI MACACO','Ao entrar, invoque nesta fileira até 2 Clones Macacos de poder 2, sem habilidade. Eles são unidades Chinesas e desaparecem ao fim do Round.','assets/cards-remake/chinesa-sun-wukong.webp','Chinesa',7,'chinese'),
('japonesa-susanoo','Susanoo','CORTE DA TEMPESTADE','Ao entrar, destrua uma unidade inimiga de poder atual até 4 na fileira oposta.','assets/cards-remake/japonesa-susanoo.webp','Japonesa',5,'japanese'),
('asteca-tezcatlipoca','Tezcatlipoca','ESPELHO DE OBSIDIANA','Ao entrar, escolha outra unidade aliada nesta fileira. Troque o poder atual dela com o de Tezcatlipoca até o fim do Round.','assets/cards-remake/asteca-tezcatlipoca.webp','Asteca',6,'aztec'),
('mesopotamica-tiamat','Tiamat','MAR PRIMORDIAL','Ao entrar, destrua outra unidade aliada desta fileira, se houver. Se destruir, Tiamat recebe metade do poder atual dela, arredondada para baixo, até o fim do Round.','assets/cards-remake/mesopotamica-tiamat.webp','Mesopotâmica',9,'mesopotamian'),
('asteca-tlaloc','Tláloc','CHUVA DE JADE','Ao entrar, as unidades inimigas já presentes na fileira central perdem 2 de poder até o fim do Round.','assets/cards-remake/asteca-tlaloc.webp','Asteca',6,'aztec'),
('japonesa-tsukuyomi','Tsukuyomi','ESPELHO DA LUA','Ao entrar, escolha outra unidade em campo. Tsukuyomi copia seu poder atual até o fim do Round, sem copiar sua habilidade.','assets/cards-remake/japonesa-tsukuyomi.webp','Japonesa',3,'japanese'),
('mesopotamica-utu-shamash','Utu - Shamash','LUZ DO JULGAMENTO','Ao entrar, remova o silêncio e as reduções de poder das outras unidades Mesopotâmicas aliadas já presentes nesta fileira.','assets/cards-remake/mesopotamica-utu-shamash.webp','Mesopotâmica',6,'mesopotamian'),
('hindu-vishnu','Vishnu','PRESERVAÇÃO DIVINA','Enquanto Vishnu estiver em campo, as outras unidades Hindus aliadas em sua fileira não podem ter seu poder reduzido por efeitos inimigos.','assets/cards-remake/hindu-vishnu.webp','Hindu',6,'hindu'),
('asteca-xipe-totec','Xipe Tótec','PELE RENOVADA','Na primeira vez que Xipe Tótec for destruído neste Round, devolva-o à mesma fileira com poder 3, sem equipamentos e sem ativar habilidades de entrada.','assets/cards-remake/asteca-xipe-totec.webp','Asteca',5,'aztec'),
('asteca-xochiquetzal','Xochiquétzal','JARDIM DA BELEZA','Enquanto estiver em campo, as outras unidades Astecas aliadas em sua fileira recebem +2 de poder.','assets/cards-remake/asteca-xochiquetzal.webp','Asteca',4,'aztec')
on conflict(card_id) do update set card_name=excluded.card_name,ability_title=excluded.ability_title,ability_text=excluded.ability_text,art_url=excluded.art_url,faction=excluded.faction,power=excluded.power,badge_key=excluded.badge_key;
insert into public.shop_catalog(item_id,title,description,kind,price,asset_path,card_id,active) values
('card-soldado-esparta','Soldado de Esparta','Cada outro Soldado de Esparta aliado na mesma fileira dobra o poder desta carta. O efeito é recíproco e acumulativo.','card',1000,'assets/cards-remake/soldado-esparta.webp','soldado-esparta',true),
('card-athena','Athena','Todas as outras cartas na mesma fileira de Athena ganham +2 pontos de poder cada.','card',1000,'assets/cards-remake/athena.webp','athena',true),
('card-lobo-alfa','Lobisomem Alfa','Recebe +2 de poder por Lobisomem Beta aliado na mesma fileira.','card',1000,'assets/cards-remake/lobo-alfa.webp','lobo-alfa',true),
('card-guardiao-nordico','Guardião Nórdico','Cada outro Guardião Nórdico aliado na mesma fileira dobra seu poder. O efeito é recíproco e acumulativo.','card',1000,'assets/cards-remake/guardiao-nordico.webp','guardiao-nordico',true),
('card-medusa','Medusa','Ao entrar, os jogadores inimigos perdem seu próximo turno. Em duplas, afeta ambos os adversários, mesmo com Heimdall.','card',1000,'assets/cards-remake/medusa.webp','medusa',true),
('card-poseidon','Poseidon','Ao entrar, o tsunami reduz em 2 o poder das unidades inimigas presentes na fileira superior. Novas entradas não são afetadas.','card',1000,'assets/cards-remake/poseidon.webp','poseidon',true),
('card-zeus','Zeus','Ao entrar, destrói até duas unidades inimigas aleatórias que possam ser afetadas.','card',1000,'assets/cards-remake/zeus.webp','zeus',true),
