('card-hindu-shiva','Shiva','Ao entrar, destrua a outra unidade de menor poder atual em cada lado. Em caso de empate, seu dono escolhe entre as empatadas.','card',1000,'assets/cards-remake/hindu-shiva.webp','hindu-shiva',true),
('card-chinesa-sun-wukong','Sun Wukong','Ao entrar, invoque nesta fileira até 2 Clones Macacos de poder 2, sem habilidade. Eles são unidades Chinesas e desaparecem ao fim do Round.','card',1000,'assets/cards-remake/chinesa-sun-wukong.webp','chinesa-sun-wukong',true),
('card-japonesa-susanoo','Susanoo','Ao entrar, destrua uma unidade inimiga de poder atual até 4 na fileira oposta.','card',1000,'assets/cards-remake/japonesa-susanoo.webp','japonesa-susanoo',true),
('card-asteca-tezcatlipoca','Tezcatlipoca','Ao entrar, escolha outra unidade aliada nesta fileira. Troque o poder atual dela com o de Tezcatlipoca até o fim do Round.','card',1000,'assets/cards-remake/asteca-tezcatlipoca.webp','asteca-tezcatlipoca',true),
('card-mesopotamica-tiamat','Tiamat','Ao entrar, destrua outra unidade aliada desta fileira, se houver. Se destruir, Tiamat recebe metade do poder atual dela, arredondada para baixo, até o fim do Round.','card',1000,'assets/cards-remake/mesopotamica-tiamat.webp','mesopotamica-tiamat',true),
('card-asteca-tlaloc','Tláloc','Ao entrar, as unidades inimigas já presentes na fileira central perdem 2 de poder até o fim do Round.','card',1000,'assets/cards-remake/asteca-tlaloc.webp','asteca-tlaloc',true),
('card-japonesa-tsukuyomi','Tsukuyomi','Ao entrar, escolha outra unidade em campo. Tsukuyomi copia seu poder atual até o fim do Round, sem copiar sua habilidade.','card',1000,'assets/cards-remake/japonesa-tsukuyomi.webp','japonesa-tsukuyomi',true),
('card-mesopotamica-utu-shamash','Utu - Shamash','Ao entrar, remova o silêncio e as reduções de poder das outras unidades Mesopotâmicas aliadas já presentes nesta fileira.','card',1000,'assets/cards-remake/mesopotamica-utu-shamash.webp','mesopotamica-utu-shamash',true),
('card-hindu-vishnu','Vishnu','Enquanto Vishnu estiver em campo, as outras unidades Hindus aliadas em sua fileira não podem ter seu poder reduzido por efeitos inimigos.','card',1000,'assets/cards-remake/hindu-vishnu.webp','hindu-vishnu',true),
('card-asteca-xipe-totec','Xipe Tótec','Na primeira vez que Xipe Tótec for destruído neste Round, devolva-o à mesma fileira com poder 3, sem equipamentos e sem ativar habilidades de entrada.','card',1000,'assets/cards-remake/asteca-xipe-totec.webp','asteca-xipe-totec',true),
('card-asteca-xochiquetzal','Xochiquétzal','Enquanto estiver em campo, as outras unidades Astecas aliadas em sua fileira recebem +2 de poder.','card',1000,'assets/cards-remake/asteca-xochiquetzal.webp','asteca-xochiquetzal',true)
on conflict(item_id) do update set title=excluded.title,description=excluded.description,asset_path=excluded.asset_path,card_id=excluded.card_id;


create or replace function public._x_rule(u jsonb) returns jsonb language sql stable set search_path='' as $$ select coalesce(public._r_data()#>array['remakeRules',public._r_id(u)],'{}'::jsonb) $$;
create or replace function public._x_room(s jsonb,t text,l integer) returns boolean language sql stable set search_path='' as $$ select (select count(*) from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]'::jsonb)) v where (v->>'lane')::integer=l)<coalesce((s->>'rowCapacity')::integer,2147483647) $$;
create or replace function public._x_bonus(s jsonb,t text,u jsonb)
returns numeric language plpgsql stable set search_path='' as $$
declare
 r jsonb:=public._x_rule(u);
 c jsonb:=public._r_card(public._r_identity(u));
 ally_unit jsonb;
 aura_rule jsonb;
 bonus_total numeric:=0;
 seen_abilities text[]:='{}';
begin
 if public._r_active(s,t,u) and r->>'op'='company' and (
  select count(*) from jsonb_array_elements(s#>array[t,'field']) as company_rows(unit_data)
  where company_rows.unit_data->>'uid'<>u->>'uid'
   and company_rows.unit_data->>'lane'=u->>'lane'
   and public._r_card(public._r_identity(company_rows.unit_data))->>'faction'=r->>'faction'
 )>=coalesce((r->>'count')::integer,1) then
  bonus_total:=bonus_total+(r->>'amount')::numeric;
 end if;

 if public._r_active(s,t,u) and r->>'op'='graveGrowth' then
  bonus_total:=bonus_total+floor((
   select count(*) from jsonb_array_elements(s#>array[t,'grave']) as grave_rows(unit_data)
   where grave_rows.unit_data->>'owner'=u->>'playedBy'
    and public._r_card(grave_rows.unit_data->>'cardId')->>'kind'='unit'
  )/(r->>'every')::numeric);
 end if;

 for ally_unit in
  select field_rows.unit_data from jsonb_array_elements(s#>array[t,'field']) as field_rows(unit_data)
  where field_rows.unit_data->>'uid'<>u->>'uid' and field_rows.unit_data->>'lane'=u->>'lane'
 loop
  if not public._r_active(s,t,ally_unit) then continue;end if;
  aura_rule:=public._x_rule(ally_unit);
  if aura_rule->>'faction' is distinct from c->>'faction' then continue;end if;
  if aura_rule->>'op'='aura' and (
   not coalesce((aura_rule->>'unique')::boolean,false)
   or not(public._r_id(ally_unit)=any(seen_abilities))
  ) then
   bonus_total:=bonus_total+(aura_rule->>'amount')::numeric;
   seen_abilities:=array_append(seen_abilities,public._r_id(ally_unit));
  end if;
  if aura_rule->>'op'='equipmentAura' then
   bonus_total:=bonus_total+least((aura_rule->>'max')::integer,
    jsonb_array_length(coalesce(u->'equipment','[]'))+jsonb_array_length(coalesce(u->'copiedEquipment','[]')));
  end if;
  if aura_rule->>'op'='occupiedAura' then
   bonus_total:=bonus_total+(
    select count(distinct occupied_rows.unit_data->>'lane')
    from jsonb_array_elements(s#>array[t,'field']) as occupied_rows(unit_data)
   );
  end if;
 end loop;
 return bonus_total;
end $$;
create or replace function public._x_block(s jsonb,t text,u jsonb,src text,k text) returns boolean language plpgsql stable set search_path='' as $$
declare v jsonb;r jsonb;
begin
 if u is null or src=t then return false;end if;if public._r_protect(s,t,(u->>'lane')::integer,src) then return true;end if;
 if u ? 'guardOwner' and k in ('destroy','steal') then return true;end if;
 for v in select value from jsonb_array_elements(s#>array[t,'field']) where value->>'lane'=u->>'lane' loop
  if not public._r_active(s,t,v) then continue;end if;r:=public._x_rule(v);if v->>'uid'=u->>'uid' and r->>'op'<>'protectMove' then continue;end if;
  if k='move' and r->>'op'='protectMove' then return true;end if;
  if r->>'faction'=public._r_card(public._r_identity(u))->>'faction' and ((k='destroy' and r->>'op'='protectDestroy') or (k='reduce' and r->>'op'='protectReduction')) then return true;end if;
 end loop;return false;
end $$;
create or replace function public._x_grave_ok(x jsonb,e jsonb,g jsonb,revive boolean default true) returns boolean language sql stable set search_path='' as $$
 select coalesce((g->>'lockedRound')::integer,0)<>coalesce((x#>>'{s,round}')::integer,1) and (not revive or not exists(select 1 from jsonb_array_elements(x#>array['s',public._r_other(e->>'team'),'field']) v where v->>'lane'=e->>'lane' and public._x_rule(v)->>'op'='blockRevive' and public._r_active(x->'s',public._r_other(e->>'team'),v))) $$;
create or replace function public._x_clean(u jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare k text;n numeric;
begin foreach k in array array['bonus','powerShift','copyOffset','reviveOffset'] loop n:=coalesce((u->>k)::numeric,0);if n<0 then u:=jsonb_set(u,array[k],'0'::jsonb);end if;end loop;if coalesce((u->>'multiplier')::numeric,1)<1 then u:=jsonb_set(u,'{multiplier}','1'::jsonb);end if;return u;end $$;
create or replace function public._x_unsilence(s jsonb,u jsonb) returns jsonb language sql immutable set search_path='' as $$ select (u-'silencedJogadas'-'silencedOwnerEnd')||jsonb_build_object('silenceExemptStamp',s->'silenceStartedBy') $$;
create or replace function public._x_draw(x jsonb,e jsonb,n integer default 1) returns jsonb language plpgsql immutable set search_path='' as $$
declare i integer;deck jsonb;hand jsonb;owner_id text:=e->>'owner';
begin deck:=coalesce(x#>array['r',owner_id,'deck'],'[]');hand:=coalesce(x#>array['r',owner_id,'hand'],'[]');for i in 1..n loop exit when jsonb_array_length(deck)=0;hand:=hand||jsonb_build_array(deck->0);deck:=deck-0;end loop;x:=jsonb_set(x,array['r',owner_id,'deck'],deck,true);return jsonb_set(x,array['r',owner_id,'hand'],hand,true);end $$;
create or replace function public._x_next(x jsonb,e jsonb,extra jsonb) returns jsonb language sql immutable set search_path='' as $$ select public._r_evt(x,(e-'selection')||extra||jsonb_build_object('op','remake')) $$;
create or replace function public._x_quiet(x jsonb,cid text,t text,owner_id text,l integer,token boolean default false) returns jsonb language plpgsql volatile set search_path='' as $$
declare queue jsonb:=coalesce(x#>'{s,effectQueue}','[]');u jsonb;
begin
 if not public._x_room(x->'s',t,l) then return x;end if;
 if token then u:=jsonb_build_object('uid',gen_random_uuid()::text,'cardId',cid,'playedBy',owner_id,'lane',l,'slot',jsonb_array_length(x#>array['s',t,'field']),'bonus',0,'multiplier',1,'equipment','[]'::jsonb,'progress',0,'token',true);x:=jsonb_set(x,array['s',t,'field'],(x#>array['s',t,'field'])||jsonb_build_array(u),true);x:=public._r_visual(x,'enter',t,jsonb_build_array(u->>'uid'));
 else x:=public._r_spawn(x,cid,t,owner_id,l,0);end if;
 x:=jsonb_set(x,'{s,effectQueue}',queue,true);return public._r_reconcile(x);
end $$;

create or replace function public._x_options(x jsonb,e jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare t text:=e->>'team';enemy text:=public._r_other(t);u jsonb:=public._r_unit(x->'s',t,e->>'uid');r jsonb:=coalesce(e->'rule',public._x_rule(u));op text:=r->>'op';phase text:=e->>'phase';result jsonb:='[]';v jsonb;c jsonb;g jsonb;list jsonb;team text;id text;p numeric;mn numeric;k text;i integer;l integer;allowed boolean;
begin
 if phase='finish' then return jsonb_build_array(public._r_option('confirm','Continuar a partida'));end if;
 if phase='lane' then v:=public._r_unit(x->'s',e->>'targetTeam',e->>'targetUid');if v is null then return result;end if;for i in 0..2 loop if i<>(v->>'lane')::integer and public._x_room(x->'s',e->>'targetTeam',i) then result:=result||jsonb_build_array(public._r_option(i::text,'Fileira '||(i+1)::text));end if;end loop;return result;end if;
 if phase in ('order','draft') then list:=case when phase='order' then e->'remaining' else coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['r',e->>'owner','deck']) with ordinality a(value,ordinality) where ordinality<=(r->>'count')::integer),'[]') end;
  for id,i in select value,ordinality::integer-1 from jsonb_array_elements_text(list) with ordinality loop result:=result||jsonb_build_array(public._r_option(i::text,coalesce(public._r_card(id)->>'name',id),id));end loop;return result;end if;
 if phase='shiva' then team:=e->>'targetTeam';select min(public._r_power(x->'s',team,value)) into mn from jsonb_array_elements(x#>array['s',team,'field']) where value->>'uid'<>e->>'uid' and not public._x_block(x->'s',team,value,t,'destroy');for v in select value from jsonb_array_elements(x#>array['s',team,'field']) where value->>'uid'<>e->>'uid' and not public._x_block(x->'s',team,value,t,'destroy') and public._r_power(x->'s',team,value)=mn loop result:=result||jsonb_build_array(public._r_option(v->>'uid',public._r_card(v->>'cardId')->>'name',v->>'cardId'));end loop;return result;end if;
 if op='choice' and phase is null then if jsonb_array_length(x#>array['r',e->>'owner','deck'])>0 then result:=result||jsonb_build_array(public._r_option('draw','Comprar 1 carta'));end if;if exists(select 1 from jsonb_array_elements(x#>array['s',t,'field']) v where v->>'uid'<>e->>'uid' and v->>'lane'=e->>'lane') then result:=result||jsonb_build_array(public._r_option('buff','Conceder +3 de poder'));end if;return result;end if;
 if op in ('recover','reviveQuiet','lockGrave') then team:=case when op='lockGrave' then enemy else t end;
  for g in select value from jsonb_array_elements(x#>array['s',team,'grave']) loop c:=public._r_card(g->>'cardId');if c='{}' or not public._card_enabled(g->>'cardId') or coalesce((c->>'specialOnly')::boolean,false) or (op<>'lockGrave' and g->>'owner' is distinct from e->>'owner') or not public._x_grave_ok(x,e,g,op='reviveQuiet') then continue;end if;
   if r ? 'kind' and r->>'kind'<>c->>'kind' or r ? 'kinds' and not(r->'kinds' ? (c->>'kind')) or r ? 'faction' and r->>'faction'<>c->>'faction' or r ? 'max' and (c->>'power')::numeric>(r->>'max')::numeric or op in ('reviveQuiet','lockGrave') and c->>'kind'<>'unit' then continue;end if;
   result:=result||jsonb_build_array(public._r_option(g->>'uid',c->>'name',g->>'cardId'));
  end loop;if coalesce((r->>'optional')::boolean,false) and jsonb_array_length(result)>0 then result:=result||jsonb_build_array(public._r_option('skip','Concluir'));end if;return result;end if;
 if op in ('equipmentDestroy','equipmentReturn') then for v in select value from jsonb_array_elements(x#>array['s',enemy,'field']) loop if public._x_block(x->'s',enemy,v,t,'equipment') then continue;end if;for id,i in select value,ordinality::integer-1 from jsonb_array_elements_text(coalesce(v->'equipment','[]')) with ordinality loop result:=result||jsonb_build_array(public._r_option((v->>'uid')||':'||i::text,(public._r_card(id)->>'name')||' · '||(public._r_card(v->>'cardId')->>'name'),id));end loop;end loop;if jsonb_array_length(result)=0 then return null;end if;return result;end if;
 if op in ('draft','reorder','drawCompany','clones','wave','waveBoth','cleanseAll','graveDraw','shiva','grow') or op in ('drawMove','drawBuff') and phase is null then return null;end if;
 if op='unsilenceDraw' and not exists(select 1 from jsonb_array_elements(x#>array['s',t,'field']) v where v->>'uid'<>e->>'uid' and not public._r_active(x->'s',t,v)) then return null;end if;
 if op='moveSelf' then return jsonb_build_array(public._r_option(e->>'uid','Mover unidade',u->>'cardId'),public._r_option('skip','Permanecer na fileira'));end if;
 if op='copyPower' then foreach team in array array[t,enemy] loop for v in select value from jsonb_array_elements(x#>array['s',team,'field']) where value->>'uid'<>e->>'uid' loop if not public._x_block(x->'s',team,v,t,'power') then result:=result||jsonb_build_array(public._r_option(team||':'||(v->>'uid'),public._r_card(v->>'cardId')->>'name',v->>'cardId'));end if;end loop;end loop;return result;end if;
 team:=case when op in ('destroy','reduce','drainGrave','purge','silence','moveEnemy','steal') or op='sacrificeHunt' and phase='hunt' then enemy else t end;
 if op='steal' and coalesce((r->>'losing')::boolean,false) and coalesce((select sum(public._r_power(x->'s',t,v)) from jsonb_array_elements(x#>array['s',t,'field']) v where v->>'lane'=e->>'lane'),0)>=coalesce((select sum(public._r_power(x->'s',enemy,v)) from jsonb_array_elements(x#>array['s',enemy,'field']) v where v->>'lane'=e->>'lane'),0) then return result;end if;
 k:=case when op='moveEnemy' then 'move' when op='steal' then 'steal' when op in ('destroy','sacrificeHunt') then 'destroy' when op in ('reduce','drainGrave','purge') then 'reduce' else 'power' end;
 for v in select value from jsonb_array_elements(x#>array['s',team,'field']) loop c:=public._r_card(public._r_identity(v));p:=public._r_power(x->'s',team,v);l:=(v->>'lane')::integer;
  if v->>'uid'=e->>'uid' or coalesce(e->'chosen','[]') ? (v->>'uid') or coalesce((r->>'opposite')::boolean,false) and v->>'lane'<>e->>'lane' or r ? 'faction' and op<>'moveAlly' and c->>'faction'<>r->>'faction' or r ? 'max' and p>(r->>'max')::numeric or public._x_block(x->'s',team,v,t,k) then continue;end if;
  if op='rally' and v->>'lane'=e->>'lane' or op<>'rally' and team=t and op not in ('moveAlly','drawMove','unsilenceDraw') and v->>'lane'<>e->>'lane' or op='sacrificeHunt' and phase='hunt' and p>(e->>'wanted')::numeric or op='unsilenceDraw' and public._r_active(x->'s',t,v) then continue;end if;
  if op in ('moveEnemy','moveAlly','drawMove') and not exists(select 1 from generate_series(0,2) l2 where l2<>l and public._x_room(x->'s',team,l2)) or op in ('rally','steal') and not public._x_room(x->'s',t,(e->>'lane')::integer) then continue;end if;
  result:=result||jsonb_build_array(public._r_option(v->>'uid',(c->>'name')||' · '||p::text||' poder · Fileira '||(l+1)::text,v->>'cardId'));
 end loop;if coalesce((r->>'optional')::boolean,false) and jsonb_array_length(result)>0 then result:=result||jsonb_build_array(public._r_option('skip','Concluir sem escolher'));end if;return result;
end $$;

create or replace function public._x_shiva(x jsonb,e jsonb,team text) returns jsonb language plpgsql volatile set search_path='' as $$
declare v jsonb;mn numeric;t text:=e->>'team';
begin select min(public._r_power(x->'s',team,value)) into mn from jsonb_array_elements(x#>array['s',team,'field']) where value->>'uid'<>e->>'uid' and not public._x_block(x->'s',team,value,t,'destroy');
 select value into v from jsonb_array_elements(x#>array['s',team,'field']) where value->>'uid'<>e->>'uid' and not public._x_block(x->'s',team,value,t,'destroy') and public._r_power(x->'s',team,value)=mn limit 1;
 if v is null then if team=t then return public._x_shiva(x,e,public._r_other(t));end if;return x;end if;
 if (select count(*) from jsonb_array_elements(x#>array['s',team,'field']) a where a->>'uid'<>e->>'uid' and not public._x_block(x->'s',team,a,t,'destroy') and public._r_power(x->'s',team,a)=mn)=1 then x:=public._r_destroy(x,team,jsonb_build_array(v->>'uid'));if team=t then return public._x_shiva(x,e,public._r_other(t));end if;return x;end if;
 return public._x_next(x,e,jsonb_build_object('phase','shiva','targetTeam',team,'choiceActor',case when team=t then e->>'owner' else v->>'playedBy' end));
end $$;

create or replace function public._x_resolve(x jsonb,e jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare t text:=e->>'team';enemy text:=public._r_other(t);owner_id text:=e->>'owner';u jsonb:=public._r_unit(x->'s',t,e->>'uid');r jsonb:=coalesce(e->'rule',public._x_rule(u));op text:=r->>'op';phase text:=e->>'phase';sel text:=e->>'selection';v jsonb;g jsonb;c jsonb;list jsonb;top_cards jsonb;remaining jsonb;ordered jsonb;team text;id text;target_id text;amount numeric;wanted numeric;p numeric;i integer;l integer;idx integer;
begin
 e:=e||jsonb_build_object('rule',r);if sel='skip' or phase='finish' then return x;end if;
 if phase='lane' then team:=e->>'targetTeam';v:=public._r_unit(x->'s',team,e->>'targetUid');l:=sel::integer;
  if v is not null and (v->>'lane')::integer<>l and public._x_room(x->'s',team,l) and not public._x_block(x->'s',team,v,t,'move') then v:=v||jsonb_build_object('lane',l);x:=public._r_set_unit(x,team,v->>'uid',v);if r ? 'amount' and (not(r ? 'faction') or public._r_card(public._r_identity(v))->>'faction'=r->>'faction') then x:=public._r_change(x,team,v->>'uid',t,(r->>'amount')::numeric);end if;end if;return x;end if;
 if phase='order' then remaining:=e->'remaining';id:=remaining->>sel::integer;remaining:=remaining-sel::integer;ordered:=coalesce(e->'ordered','[]')||jsonb_build_array(id);
  if jsonb_array_length(remaining)>0 then return public._x_next(x,e,jsonb_build_object('phase','order','remaining',remaining,'ordered',ordered));end if;
  top_cards:=x#>array['r',owner_id,'deck'];top_cards:=case when e->>'destination'='top' then ordered||top_cards else top_cards||ordered end;x:=jsonb_set(x,array['r',owner_id,'deck'],top_cards,true);if coalesce((e->>'drawAfter')::boolean,false) then x:=public._x_draw(x,e);end if;return x;end if;
 if phase='draft' then select coalesce(jsonb_agg(value order by ordinality) filter(where ordinality<=(r->>'count')::integer),'[]'),coalesce(jsonb_agg(value order by ordinality) filter(where ordinality>(r->>'count')::integer),'[]') into top_cards,remaining from jsonb_array_elements(x#>array['r',owner_id,'deck']) with ordinality a(value,ordinality);
  id:=top_cards->>sel::integer;top_cards:=top_cards-sel::integer;x:=jsonb_set(x,array['r',owner_id,'deck'],remaining,true);if id is not null then x:=jsonb_set(x,array['r',owner_id,'hand'],(x#>array['r',owner_id,'hand'])||jsonb_build_array(id),true);end if;
  if jsonb_array_length(top_cards)>0 then return public._x_next(x,e,jsonb_build_object('phase','order','remaining',top_cards,'ordered','[]'::jsonb,'destination','bottom'));end if;return x;end if;
 if phase='shiva' then team:=e->>'targetTeam';x:=public._r_destroy(x,team,jsonb_build_array(sel));if team=t then x:=public._x_shiva(x,e,enemy);end if;return x;end if;
 case op
 when 'draft' then return public._x_next(x,e,jsonb_build_object('phase','draft'));
 when 'reorder' then select coalesce(jsonb_agg(value order by ordinality) filter(where ordinality<=(r->>'count')::integer),'[]'),coalesce(jsonb_agg(value order by ordinality) filter(where ordinality>(r->>'count')::integer),'[]') into top_cards,remaining from jsonb_array_elements(x#>array['r',owner_id,'deck']) with ordinality a(value,ordinality);x:=jsonb_set(x,array['r',owner_id,'deck'],remaining,true);if jsonb_array_length(top_cards)>0 then return public._x_next(x,e,jsonb_build_object('phase','order','remaining',top_cards,'ordered','[]'::jsonb,'destination','top','drawAfter',true));end if;
 when 'choice' then if sel='draw' then return public._x_draw(x,e);else return public._x_next(x,e,jsonb_build_object('phase','buff','rule',jsonb_build_object('op','buff','amount',3)));end if;
 when 'buff' then return public._r_change(x,t,sel,t,(r->>'amount')::numeric);
 when 'recover','reviveQuiet','lockGrave' then team:=case when op='lockGrave' then enemy else t end;select value into g from jsonb_array_elements(x#>array['s',team,'grave']) where value->>'uid'=sel limit 1;if g is null or not public._x_grave_ok(x,e,g,op='reviveQuiet') then return x;end if;
  if op='lockGrave' then x:=jsonb_set(x,array['s',team,'grave'],coalesce((select jsonb_agg(case when value->>'uid'=sel then value||jsonb_build_object('lockedRound',x#>'{s,round}') else value end order by ordinality) from jsonb_array_elements(x#>array['s',team,'grave']) with ordinality a(value,ordinality)),'[]'),true);if jsonb_array_length(coalesce(e->'chosen','[]'))+1<(r->>'count')::integer then return public._x_next(x,e,jsonb_build_object('chosen',coalesce(e->'chosen','[]')||jsonb_build_array(sel)));end if;return x;end if;
  if op='reviveQuiet' and not public._x_room(x->'s',t,(e->>'lane')::integer) then return x;end if;
  x:=jsonb_set(x,array['s',team,'grave'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',team,'grave']) with ordinality a(value,ordinality) where value->>'uid'<>sel),'[]'),true);x:=public._r_grave_sync(x,team);
  if op='recover' then return jsonb_set(x,array['r',owner_id,'hand'],(x#>array['r',owner_id,'hand'])||jsonb_build_array(g->'cardId'),true);else x:=public._x_quiet(x,g->>'cardId',t,owner_id,(e->>'lane')::integer);if g->>'rebornRound'=x#>>'{s,round}' then select value into v from jsonb_array_elements(x#>array['s',t,'field']) with ordinality a(value,ordinality) where value->>'cardId'=g->>'cardId' and value->>'playedBy'=owner_id order by ordinality desc limit 1;if v is not null then x:=public._r_set_unit(x,t,v->>'uid',public._x_memory(x->'s',v,g));end if;end if;return x;end if;
 when 'drawCompany' then x:=public._x_draw(x,e);if exists(select 1 from jsonb_array_elements(x#>array['s',t,'field']) v where v->>'uid'<>e->>'uid' and v->>'lane'=e->>'lane' and public._r_card(public._r_identity(v))->>'faction'=r->>'faction') then x:=public._r_change(x,t,e->>'uid',t,(r->>'amount')::numeric);end if;
 when 'drawBuff' then if phase is null then return public._x_next(public._x_draw(x,e),e,jsonb_build_object('phase','buff'));end if;return public._r_change(x,t,sel,t,(r->>'amount')::numeric);
 when 'drawMove' then if phase is null then return public._x_next(public._x_draw(x,e),e,jsonb_build_object('phase','move'));end if;return public._x_next(x,e,jsonb_build_object('phase','lane','targetTeam',t,'targetUid',sel));
 when 'moveAlly','moveSelf','moveEnemy' then return public._x_next(x,e,jsonb_build_object('phase','lane','targetTeam',case when op='moveEnemy' then enemy else t end,'targetUid',sel));
 when 'rally' then v:=public._r_unit(x->'s',t,sel);if v is not null and v->>'lane'<>e->>'lane' and public._x_room(x->'s',t,(e->>'lane')::integer) then x:=public._r_set_unit(x,t,sel,v||jsonb_build_object('lane',e->'lane'));x:=public._r_change(x,t,sel,t,(r->>'amount')::numeric);end if;
 when 'bounce' then v:=public._r_unit(x->'s',t,sel);if v is not null then x:=jsonb_set(x,array['s',t,'field'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',t,'field']) with ordinality a(value,ordinality) where value->>'uid'<>sel),'[]'),true);id:=coalesce(v->>'eclipseOriginalCardId',v->>'sourceCardId',case when v->>'cardId'='lukyan-rei-de-todos' then 'lukyan' else v->>'cardId' end);if not coalesce((v->>'token')::boolean,false) then x:=jsonb_set(x,array['r',owner_id,'hand'],(x#>array['r',owner_id,'hand'])||jsonb_build_array(id),true);end if;for id in select jsonb_array_elements_text(coalesce(v->'equipment','[]')) loop x:=jsonb_set(x,array['s',t,'grave'],(x#>array['s',t,'grave'])||jsonb_build_array(jsonb_build_object('uid',gen_random_uuid()::text,'cardId',id,'owner',coalesce(v#>>array['equipmentOwners',id],v->>'playedBy'),'progress',0)),true);end loop;x:=public._r_grave_sync(x,t);x:=public._r_change(x,t,e->>'uid',t,(r->>'amount')::numeric);end if;
 when 'steal' then v:=public._r_unit(x->'s',enemy,sel);if v is not null and not public._x_block(x->'s',enemy,v,t,'steal') and public._x_room(x->'s',t,(e->>'lane')::integer) then x:=jsonb_set(x,array['s',enemy,'field'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',enemy,'field']) with ordinality a(value,ordinality) where value->>'uid'<>sel),'[]'),true);v:=v||jsonb_build_object('lane',e->'lane','playedBy',owner_id);x:=jsonb_set(x,array['s',t,'field'],(x#>array['s',t,'field'])||jsonb_build_array(v),true);x:=public._r_visual(x,'hearts',t,jsonb_build_array(sel));end if;
 when 'reduce','drainGrave' then amount:=case when op='drainGrave' then (select count(*) from jsonb_array_elements(x#>array['s',enemy,'grave']) g where g->>'owner'=public._r_unit(x->'s',enemy,sel)->>'playedBy' and public._r_card(g->>'cardId')->>'kind'='unit') else (r->>'amount')::numeric end;x:=public._r_change(x,enemy,sel,t,-amount);if op='reduce' and jsonb_array_length(coalesce(e->'chosen','[]'))+1<coalesce((r->>'count')::integer,1) then return public._x_next(x,e,jsonb_build_object('chosen',coalesce(e->'chosen','[]')||jsonb_build_array(sel)));end if;
 when 'wave','waveBoth' then foreach team in array case when op='waveBoth' then array[t,enemy] else array[enemy] end loop for v in select value from jsonb_array_elements(x#>array['s',team,'field']) where value->>'uid'<>e->>'uid' and (value->>'lane')::integer=coalesce((r->>'fixedLane')::integer,(e->>'lane')::integer) loop x:=public._r_change(x,team,v->>'uid',t,-(r->>'amount')::numeric);end loop;end loop;
 when 'destroy' then x:=public._r_destroy(x,enemy,jsonb_build_array(sel));if (coalesce((r->>'costOnAttempt')::boolean,false) or public._r_unit(x->'s',enemy,sel) is null) and r ? 'selfCost' then x:=public._r_change(x,t,e->>'uid',t,-(r->>'selfCost')::numeric);end if;
 when 'sacrificeHunt' then if phase='hunt' then return public._r_destroy(x,enemy,jsonb_build_array(sel));end if;v:=public._r_unit(x->'s',t,sel);wanted:=public._r_power(x->'s',t,v);x:=public._r_destroy(x,t,jsonb_build_array(sel));if public._r_unit(x->'s',t,sel) is null then return public._x_next(x,e,jsonb_build_object('phase','hunt','wanted',wanted));end if;
 when 'sacrificeBuff','sacrificeFeed' then v:=public._r_unit(x->'s',t,sel);if v is null then return x;end if;wanted:=public._r_power(x->'s',t,v);list:=x#>array['s',t,'field'];x:=public._r_destroy(x,t,jsonb_build_array(sel));if public._r_unit(x->'s',t,sel) is null then if op='sacrificeFeed' then x:=public._r_change(x,t,e->>'uid',t,floor(wanted/2));else for v in select value from jsonb_array_elements(list) where value->>'uid'<>sel and value->>'lane'=e->>'lane' loop x:=public._r_change(x,t,v->>'uid',t,(r->>'amount')::numeric);end loop;end if;end if;
 when 'copyPower' then team:=split_part(sel,':',1);target_id:=split_part(sel,':',2);v:=public._r_unit(x->'s',team,target_id);if v is not null then u:=u||jsonb_build_object('powerShift',coalesce((u->>'powerShift')::numeric,0)+public._r_power(x->'s',team,v)-public._r_power(x->'s',t,u));x:=public._r_set_unit(x,t,u->>'uid',u);end if;
 when 'swap' then v:=public._r_unit(x->'s',t,sel);if v is not null then p:=public._r_power(x->'s',t,u);wanted:=public._r_power(x->'s',t,v);u:=u||jsonb_build_object('powerShift',coalesce((u->>'powerShift')::numeric,0)+wanted-p);v:=v||jsonb_build_object('powerShift',coalesce((v->>'powerShift')::numeric,0)+p-wanted);x:=public._r_set_unit(public._r_set_unit(x,t,u->>'uid',u),t,v->>'uid',v);end if;
 when 'purge' then v:=public._r_unit(x->'s',enemy,sel);if v is not null and not public._x_block(x->'s',enemy,v,t,'reduce') then v:=v||jsonb_build_object('mutedEquipment',coalesce(v->'equipment','[]')||coalesce(v->'copiedEquipment','[]'),'equipmentMuted',false,'bonus',least(0,coalesce((v->>'bonus')::numeric,0)),'multiplier',least(1,coalesce((v->>'multiplier')::numeric,1)),'powerShift',least(0,coalesce((v->>'powerShift')::numeric,0)),'copyOffset',least(0,coalesce((v->>'copyOffset')::numeric,0)),'reviveOffset',least(0,coalesce((v->>'reviveOffset')::numeric,0)),'progress',0);x:=public._r_set_unit(x,enemy,sel,v);end if;
 when 'cleanse' then v:=public._r_unit(x->'s',t,sel);if v is not null then x:=public._r_set_unit(x,t,sel,public._x_clean(v));if r ? 'amount' then x:=public._r_change(x,t,sel,t,(r->>'amount')::numeric);end if;if jsonb_array_length(coalesce(e->'chosen','[]'))+1<coalesce((r->>'count')::integer,1) then return public._x_next(x,e,jsonb_build_object('chosen',coalesce(e->'chosen','[]')||jsonb_build_array(sel)));end if;end if;
 when 'cleanseAll' then for v in select value from jsonb_array_elements(x#>array['s',t,'field']) where value->>'uid'<>e->>'uid' and value->>'lane'=e->>'lane' and public._r_card(public._r_identity(value))->>'faction'=r->>'faction' loop x:=public._r_set_unit(x,t,v->>'uid',public._x_unsilence(x->'s',public._x_clean(v)));end loop;
 when 'unsilenceDraw' then v:=public._r_unit(x->'s',t,sel);if v is null then x:=public._x_draw(x,e);else x:=public._r_set_unit(x,t,sel,public._x_unsilence(x->'s',v));end if;
 when 'silence' then v:=public._r_unit(x->'s',enemy,sel);if v is not null and not public._x_block(x->'s',enemy,v,t,'silence') then v:=v||jsonb_build_object('silencedStamp',owner_id||':'||coalesce(x#>>array['r',owner_id,'turnsTaken'],'0'));if coalesce((r->>'ownerEnd')::boolean,false) then v:=v||jsonb_build_object('silencedOwnerEnd',true);else v:=v||jsonb_build_object('silencedJogadas',(r->>'turns')::integer);end if;x:=public._r_set_unit(x,enemy,sel,v);end if;
 when 'guard' then v:=public._r_unit(x->'s',t,sel);if v is not null then x:=public._r_set_unit(x,t,sel,v||jsonb_build_object('guardOwner',owner_id,'guardStamp',owner_id||':'||coalesce(x#>>array['r',owner_id,'turnsTaken'],'0')));end if;
 when 'equipmentDestroy','equipmentReturn' then if sel is null then if r ? 'fallback' then x:=public._r_change(x,t,e->>'uid',t,(r->>'fallback')::numeric);end if;return x;end if;target_id:=split_part(sel,':',1);idx:=split_part(sel,':',2)::integer;v:=public._r_unit(x->'s',enemy,target_id);if v is null or public._x_block(x->'s',enemy,v,t,'equipment') then return x;end if;id:=v#>>array['equipment',idx::text];if id is null then return x;end if;v:=jsonb_set(v,'{equipment}',(v->'equipment')-idx,true);x:=public._r_set_unit(x,enemy,target_id,v);
  if op='equipmentReturn' then target_id:=coalesce(v#>>array['equipmentOwners',id],v->>'playedBy');if x#>array['r',target_id] is null then select key into target_id from jsonb_each(x->'r') where value->>'team'=enemy limit 1;end if;x:=jsonb_set(x,array['r',target_id,'hand'],(x#>array['r',target_id,'hand'])||jsonb_build_array(id),true);x:=public._x_draw(x,e);
  else x:=jsonb_set(x,array['s',enemy,'grave'],(x#>array['s',enemy,'grave'])||jsonb_build_array(jsonb_build_object('uid',gen_random_uuid()::text,'cardId',id,'owner',coalesce(v#>>array['equipmentOwners',id],v->>'playedBy'),'progress',0)),true);x:=public._r_grave_sync(x,enemy);end if;
 when 'clones' then for i in 1..(r->>'count')::integer loop exit when not public._x_room(x->'s',t,(e->>'lane')::integer);x:=public._x_quiet(x,'clone-macaco',t,owner_id,(e->>'lane')::integer,true);end loop;
 when 'graveDraw' then select count(*) into i from jsonb_array_elements(x#>array['s',t,'grave']) g where g->>'owner'=owner_id and public._r_card(g->>'cardId')->>'kind'='unit';if i>0 then x:=public._x_draw(x,e);end if;if i>=(r->>'count')::integer then x:=public._r_change(x,t,e->>'uid',t,(r->>'amount')::numeric);end if;
 when 'shiva' then return public._x_shiva(x,e,t);
 else null;
 end case;return public._r_reconcile(x);
end $$;

-- Keep the previous effect dispatcher so old cards retain their rules.
do $backup_functions$
declare signature text;definition text;original_name text;
begin
 foreach signature in array array['_r_options(jsonb,jsonb)','_r_resolve(jsonb,jsonb)','_r_grave_ok(jsonb,jsonb,jsonb)','_r_change(jsonb,text,text,text,numeric,numeric)','_r_turn_start(jsonb,jsonb,text)','_r_turn_end(jsonb,text,text,integer)','_r_clear_round(jsonb)'] loop
  original_name:=split_part(signature,'(',1);
  if to_regprocedure('public.'||replace(signature,original_name,original_name||'_before_remake')) is null then
   definition:=pg_get_functiondef(('public.'||signature)::regprocedure);
   definition:=replace(definition,'FUNCTION public.'||original_name||'(','FUNCTION public.'||original_name||'_before_remake(');execute definition;
  end if;
 end loop;
end $backup_functions$;

create or replace function public._r_active(s jsonb,t text,u jsonb) returns boolean language sql stable set search_path='' as $$
 select not(coalesce((u->>'silencedJogadas')::integer,0)>0 or coalesce((u->>'silencedOwnerEnd')::boolean,false)) and
 (public._r_live(s) or coalesce(u->>'silenceExemptStamp'=s->>'silenceStartedBy',false) or coalesce(s->>'silenceTeam'=public._r_other(t) and public._r_shield(s,t,coalesce((u->>'lane')::integer,0)),false)) $$;

do $power_hooks$
declare d text;a text;b text;
begin
 d:=pg_get_functiondef('public._r_power(jsonb,text,jsonb,integer)'::regprocedure);
 if position('remake_power_v40' in d)=0 then
  a:='p:=coalesce((u->>''copiedBasePower'')::numeric,p)+coalesce((u->>''bonus'')::numeric,0);';
  b:=a||'p:=p+public._x_bonus(s,t,u); /* remake_power_v40 */';
  if position(a in d)=0 then raise exception 'Motor de poder incompatível com a coleção Remake.';end if;d:=replace(d,a,b);
  d:=replace(d,'if public._r_gear_compatible(gear,u) then','if public._r_gear_compatible(gear,u) and not(coalesce(u->''mutedEquipment'',''[]''::jsonb) ? gear) then');
  d:=replace(d,'for gear in select jsonb_array_elements_text(coalesce(u->''equipment'',''[]''::jsonb)||coalesce(u->''copiedEquipment'',''[]''::jsonb)) loop','for gear in select jsonb_array_elements_text(case when coalesce((u->>''equipmentMuted'')::boolean,false) then ''[]''::jsonb else coalesce(u->''equipment'',''[]''::jsonb)||coalesce(u->''copiedEquipment'',''[]''::jsonb) end) loop');
  d:=replace(d,'if id=''lukyan-rei-de-todos'' then p:=p*power(2::numeric,greatest(0,jsonb_array_length(a->''field'')-1));end if;','if id=''lukyan-rei-de-todos'' then p:=p+greatest(0,jsonb_array_length(a->''field'')-1);end if;');execute d;
 end if;
end $power_hooks$;

create or replace function public._r_change(x jsonb,t text,id text,src text,amount numeric default 0,mult numeric default 1) returns jsonb language plpgsql immutable set search_path='' as $$
begin if amount<0 and public._x_block(x->'s',t,public._r_unit(x->'s',t,id),src,'reduce') then return x;end if;return public._r_change_before_remake(x,t,id,src,amount,mult);end $$;
create or replace function public._r_grave_ok(x jsonb,e jsonb,g jsonb) returns boolean language sql stable set search_path='' as $$ select public._x_grave_ok(x,e,g) and public._r_grave_ok_before_remake(x,e,g) $$;
create or replace function public._r_options(x jsonb,e jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare result jsonb;v jsonb;team text:=public._r_other(e->>'team');k text;mn numeric;
begin
 if e->>'op'='remake' then return public._x_options(x,e);end if;
 if e->>'op'='destroy_strongest' then select max(public._r_power(x->'s',team,value)) into mn from jsonb_array_elements(x#>array['s',team,'field']) where not public._x_block(x->'s',team,value,e->>'team','destroy');select coalesce(jsonb_agg(public._r_option(value->>'uid',public._r_card(value->>'cardId')->>'name',value->>'cardId')),'[]') into result from jsonb_array_elements(x#>array['s',team,'field']) where public._r_power(x->'s',team,value)=mn and not public._x_block(x->'s',team,value,e->>'team','destroy');return result;end if;
 result:=public._r_options_before_remake(x,e);
 if e->>'op' in ('steal','anubis') then select coalesce(jsonb_agg(value order by ordinality),'[]') into result from jsonb_array_elements(result) with ordinality a(value,ordinality) where value->>'value'='skip' or not public._x_block(x->'s',team,public._r_unit(x->'s',team,value->>'value'),e->>'team',case when e->>'op'='anubis' then 'destroy' else 'steal' end);end if;
 return result;
end $$;

create or replace function public._r_destroy(x jsonb,t text,ids jsonb,killed boolean default true) returns jsonb language plpgsql volatile set search_path='' as $$
declare u jsonb;v jsonb;g jsonb;guard jsonb;r jsonb;gear text;original text;src text:=coalesce(x#>>'{s,remakeSource}',public._r_other(t));fresh_id text;was_live boolean;grave_id text;death numeric;
begin
 for u in select value from jsonb_array_elements(coalesce(x#>array['s',t,'field'],'[]'::jsonb)) where ids ? (value->>'uid') loop
  if public._r_unit(x->'s',t,u->>'uid') is null then continue;end if;
  if killed and public._x_block(x->'s',t,u,src,'destroy') then continue;end if;
  if killed and src<>t then
   select value into guard from jsonb_array_elements(x#>array['s',t,'field']) v where value->>'uid'<>u->>'uid' and value->>'lane'=u->>'lane' and public._r_active(x->'s',t,value) and public._x_rule(value)->>'op'='saveOnce' and not coalesce((value->>'savedOnce')::boolean,false) and public._x_rule(value)->>'faction'=public._r_card(public._r_identity(u))->>'faction' limit 1;
   if guard is not null then x:=public._r_set_unit(x,t,guard->>'uid',guard||jsonb_build_object('savedOnce',true));x:=public._r_visual(x,'shield',t,jsonb_build_array(u->>'uid'));continue;end if;
  end if;
  was_live:=public._r_active(x->'s',t,u);death:=public._r_power(x->'s',t,u);
  x:=jsonb_set(x,array['s',t,'field'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',t,'field']) with ordinality a(value,ordinality) where value->>'uid'<>u->>'uid'),'[]'),true);
  if coalesce((u->>'token')::boolean,false) then if killed then for v in select value from jsonb_array_elements(x#>array['s',t,'field']) where value->>'lane'=u->>'lane' loop if public._x_rule(v)->>'op'='mourning' and public._r_active(x->'s',t,v) and not coalesce((v->>'mourningUsed')::boolean,false) then x:=public._r_set_unit(x,t,v->>'uid',v||jsonb_build_object('mourningUsed',true));x:=public._r_change(x,t,v->>'uid',t,4);end if;end loop;end if;continue;end if;
  if killed then x:=public._r_visual(x,'destroy',t,jsonb_build_array(u->>'uid'));end if;
  original:=coalesce(u->>'eclipseOriginalCardId',u->>'sourceCardId',case when u->>'cardId'='lukyan-rei-de-todos' then 'lukyan' else u->>'cardId' end);grave_id:=gen_random_uuid()::text;
  g:=jsonb_build_object('uid',grave_id,'cardId',original,'owner',u->>'playedBy','progress',coalesce((u->>'progress')::integer,0),'deathPower',death,'rebornOnce',coalesce((u->>'rebornOnce')::boolean,false),'savedOnce',coalesce((u->>'savedOnce')::boolean,false),'mourningUsed',coalesce((u->>'mourningUsed')::boolean,false),'rebornRound',x#>'{s,round}');
  x:=jsonb_set(x,array['s',t,'grave'],coalesce(x#>array['s',t,'grave'],'[]')||jsonb_build_array(g),true);
  for gear in select jsonb_array_elements_text(coalesce(u->'equipment','[]')) loop x:=jsonb_set(x,array['s',t,'grave'],(x#>array['s',t,'grave'])||jsonb_build_array(jsonb_build_object('uid',gen_random_uuid()::text,'cardId',gear,'owner',coalesce(u#>>array['equipmentOwners',gear],u->>'playedBy'),'progress',0)),true);end loop;
  if killed and was_live and public._r_id(u)='osiris' then x:=public._r_evt(x,jsonb_build_object('op','osiris','team',t,'owner',u->>'playedBy','lane',u->'lane','shielded',public._r_shield(x->'s',t,(u->>'lane')::integer)));end if;
  if killed then
   for v in select value from jsonb_array_elements(x#>array['s',t,'field']) where value->>'lane'=u->>'lane' loop
    if public._x_rule(v)->>'op'='mourning' and public._r_active(x->'s',t,v) and not coalesce((v->>'mourningUsed')::boolean,false) then x:=public._r_set_unit(x,t,v->>'uid',v||jsonb_build_object('mourningUsed',true));x:=public._r_change(x,t,v->>'uid',t,4);end if;
   end loop;
   if was_live and public._x_rule(u)->>'op'='rebirth' and not coalesce((u->>'rebornOnce')::boolean,false) and public._x_room(x->'s',t,(u->>'lane')::integer) then
    x:=jsonb_set(x,array['s',t,'grave'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',t,'grave']) with ordinality a(value,ordinality) where value->>'uid'<>grave_id),'[]'),true);
    x:=public._x_quiet(x,u->>'cardId',t,u->>'playedBy',(u->>'lane')::integer);
    select value into v from jsonb_array_elements(x#>array['s',t,'field']) with ordinality a(value,ordinality) where value->>'cardId'=u->>'cardId' and value->>'playedBy'=u->>'playedBy' order by ordinality desc limit 1;
    v:=v||jsonb_build_object('rebornOnce',true,'powerShift',3-public._r_power(x->'s',t,v));x:=public._r_set_unit(x,t,v->>'uid',v);
   end if;
  end if;
 end loop;return public._r_grave_sync(x,t);
end $$;

create or replace function public._r_resolve(x jsonb,e jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare u jsonb:=public._r_unit(x->'s',e->>'team',e->>'uid');v jsonb;team text:=public._r_other(e->>'team');
begin
 if e->>'op'='remake' and not public._r_enabled(x,e) then return x;end if;
 x:=jsonb_set(x,'{s,remakeSource}',to_jsonb(e->>'team'),true);
 if e->>'op'='remake' then x:=public._x_resolve(x,e);
 else
  if e->>'op'='steal' and public._x_block(x->'s',team,public._r_unit(x->'s',team,e->>'selection'),e->>'team','steal') then return x#-'{s,remakeSource}';end if;
  x:=public._r_resolve_before_remake(x,e);
 end if;return x#-'{s,remakeSource}';
end $$;

do $drain_actor$
declare d text;
begin d:=pg_get_functiondef('public._r_drain(jsonb,boolean)'::regprocedure);d:=replace(d,'''actor'',e->>''owner''','''actor'',coalesce(e->>''choiceActor'',e->>''owner'')');execute d;end $drain_actor$;

create or replace function public._r_turn_start(s jsonb,resources jsonb,actor text) returns jsonb language plpgsql volatile set search_path='' as $$
declare t text;v jsonb;x jsonb:=jsonb_build_object('s',s,'r',resources);
begin foreach t in array array['player_one','player_two'] loop for v in select value from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]')) where value->>'guardOwner'=actor and value->>'guardStamp' is distinct from actor||':'||coalesce(resources#>>array[actor,'turnsTaken'],'0') loop x:=public._r_set_unit(x,t,v->>'uid',v-'guardOwner'-'guardStamp');end loop;end loop;return public._r_turn_start_before_remake(x->'s',resources,actor);end $$;
create or replace function public._r_turn_end(s jsonb,actor text,t text,turn_no integer) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb:=jsonb_build_object('s',s,'r','{}'::jsonb);u jsonb;r jsonb;team text;stamp text:=actor||':'||turn_no::text;
begin
 if s#>>array['endedTurns',actor]=coalesce(s->>'round','1')||':'||turn_no::text then return s;end if;
 for u in select value from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]')) where value->>'playedBy'=actor loop r:=public._x_rule(u);
  if public._r_active(s,t,u) and r->>'op'='grow' and (not coalesce((r->>'company')::boolean,false) or (select count(*) from jsonb_array_elements(s#>array[t,'field']) v where v->>'lane'=u->>'lane')>1) and (not coalesce((r->>'climate')::boolean,false) or s#>>'{sharedZones,climate}' is not null) then x:=public._r_change(x,t,u->>'uid',t,(r->>'amount')::numeric);end if;
 end loop;
 -- Owner-end expiry is applied after end-of-turn growth, while the silence still acts.
 s:=public._r_turn_end_before_remake(x->'s',actor,t,turn_no);x:=jsonb_build_object('s',s,'r','{}'::jsonb);
 foreach team in array array['player_one','player_two'] loop for u in select value from jsonb_array_elements(coalesce(s#>array[team,'field'],'[]')) loop
  
  if coalesce((u->>'silencedOwnerEnd')::boolean,false) and u->>'playedBy'=actor then u:=u-'silencedOwnerEnd';end if;
  if coalesce((u->>'silencedJogadas')::integer,0)>0 and u->>'silencedStamp' is distinct from stamp then u:=u||jsonb_build_object('silencedJogadas',(u->>'silencedJogadas')::integer-1);end if;x:=public._r_set_unit(x,team,u->>'uid',u);
 end loop;end loop;return public._r_reconcile(x)->'s';
end $$;

create or replace function public._r_clear_round(s jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare t text;
begin s:=public._r_clear_round_before_remake(s);foreach t in array array['player_one','player_two'] loop s:=jsonb_set(s,array[t,'grave'],coalesce((select jsonb_agg(value-'lockedRound'-'rebornOnce'-'rebornRound'-'savedOnce'-'mourningUsed' order by ordinality) from jsonb_array_elements(coalesce(s#>array[t,'grave'],'[]')) with ordinality a(value,ordinality)),'[]'),true);end loop;return s;end $$;

do $revive_state$
declare d text;a text;b text;
begin
 d:=pg_get_functiondef('public._r_resolve_before_remake(jsonb,jsonb)'::regprocedure);
 a:='x:=public._r_spawn(x,cid,t,owner_id,lane,coalesce((g->>''progress'')::integer,0));';
 b:=a||'if coalesce((g->>''rebornOnce'')::boolean,false) and g->>''rebornRound''=x#>>''{s,round}'' then select value into v from jsonb_array_elements(x#>array[''s'',t,''field'']) with ordinality a(value,ordinality) where value->>''cardId''=cid and value->>''playedBy''=owner_id order by ordinality desc limit 1;if v is not null then x:=public._r_set_unit(x,t,v->>''uid'',v||jsonb_build_object(''rebornOnce'',true));end if;end if;';
 if position(b in d)=0 then d:=replace(d,a,b);end if;
 d:=replace(d,'(public._r_card(a->>''cardId'')->''tags'') ?| array[''heroi'',''soldado'',''espartano'']','((public._r_card(a->>''cardId'')->''tags'') ?| array[''heroi'',''soldado'',''espartano''] or public._r_card(a->>''cardId'')->>''characterClass''=''Herói'')');
 execute d;
end $revive_state$;

-- An opponent may resolve only a pending choice explicitly assigned to them.
-- The original turn owner confirms the completed chain, so turn advancement
-- continues through the existing executor and cannot skip or steal a turn.
do $preserve_executor$
declare d text;
begin if to_regprocedure('public._security_submit_game_action_v37_before_remake(uuid,jsonb)') is null then d:=pg_get_functiondef('public._security_submit_game_action_v37(uuid,jsonb)'::regprocedure);d:=replace(d,'FUNCTION public._security_submit_game_action_v37(','FUNCTION public._security_submit_game_action_v37_before_remake(');execute d;end if;end $preserve_executor$;
create or replace function public._security_submit_game_action_v37(p_match_id uuid,p_action jsonb) returns public.game_matches language plpgsql volatile security definer set search_path='' as $$
declare g public.game_matches%rowtype;uid uuid:=auth.uid();resources jsonb:='{}';x jsonb;row_item record;t text;participant uuid;pending jsonb;e jsonb;
begin
 select * into g from public.game_matches where id=p_match_id and uid in(player_one,player_two,player_three,player_four) for update;
 if not found then raise exception 'Partida indisponível.';end if;pending:=g.state->'pendingEffect';
 if p_action->>'type'='resolve_effect' and g.turn_user<>uid and pending->>'actor'=uid::text then
  if g.status<>'active' then raise exception 'Esta partida já terminou.';end if;
  if coalesce(g.team_size,1)=2 then
   for row_item in select ps.player_id,ps.private_state,mp.team from public.duo_player_states ps join public.duo_match_players mp on mp.match_id=ps.match_id and mp.player_id=ps.player_id where ps.match_id=g.id for update of ps loop
    t:=case when row_item.team=1 then 'player_one' else 'player_two' end;
    resources:=resources||jsonb_build_object(row_item.player_id::text,row_item.private_state||jsonb_build_object('team',t));
   end loop;
  else resources:=jsonb_build_object(g.player_one::text,(g.state->'player_one')||jsonb_build_object('team','player_one'),g.player_two::text,(g.state->'player_two')||jsonb_build_object('team','player_two'));end if;
  x:=public._r_action(g.state,resources,uid::text,p_action);
  if x#>'{s,pendingEffect}' is null then
   e:=jsonb_build_object('op','remake','rule',jsonb_build_object('op','finish'),'phase','finish','team',pending#>>'{event,team}','owner',pending#>>'{event,owner}','uid',pending#>>'{event,uid}','lane',pending#>'{event,lane}');
   x:=jsonb_set(x,'{s,pendingEffect}',jsonb_build_object('id',gen_random_uuid()::text,'actor',g.turn_user::text,'event',e,'title','Habilidade resolvida','options',jsonb_build_array(public._r_option('confirm','Continuar a partida'))),true);
  end if;
  if coalesce(g.team_size,1)=2 then
   for participant in select player_id from public.duo_player_states where match_id=g.id loop update public.duo_player_states set private_state=public._r_personal(x#>array['r',participant::text]) where match_id=g.id and player_id=participant;end loop;
  else x:=jsonb_set(x,'{s,player_one}',(x#>'{s,player_one}')||public._r_personal(x#>array['r',g.player_one::text]),true);x:=jsonb_set(x,'{s,player_two}',(x#>'{s,player_two}')||public._r_personal(x#>array['r',g.player_two::text]),true);end if;
  update public.game_matches set state=x->'s',turn_deadline=clock_timestamp()+interval '30 seconds' where id=g.id returning * into g;return g;
 end if;
 return public._security_submit_game_action_v37_before_remake(p_match_id,p_action);
end $$;
revoke all on function public._security_submit_game_action_v37(uuid,jsonb) from public,anon,authenticated;

-- Choice options and the reordered private deck must never be sent to rivals
-- or spectators. The actor receives the real pending event through this RPC.
do $getter_backup$
declare d text;
begin if to_regprocedure('public._x_get_online_match_before_remake(uuid)') is null then d:=pg_get_functiondef('public.get_online_match(uuid)'::regprocedure);d:=replace(d,'FUNCTION public.get_online_match(','FUNCTION public._x_get_online_match_before_remake(');execute d;end if;end $getter_backup$;
create or replace function public.get_online_match(p_match_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare result jsonb;pending jsonb;
begin result:=public._x_get_online_match_before_remake(p_match_id);pending:=result#>'{match,state,pendingEffect}';
 if jsonb_typeof(pending)='object' and pending->>'actor' is distinct from auth.uid()::text then
  result:=jsonb_set(result,'{match,state,pendingEffect}',jsonb_build_object('id',pending->'id','actor',pending->'actor','title','Outro jogador está resolvendo uma habilidade.'),true);
 end if;return result;
end $$;
revoke all on function public.get_online_match(uuid) from public,anon;
grant execute on function public.get_online_match(uuid) to authenticated;

-- Existing area attacks choose eligible units before applying their effects.
create or replace function public._r_resolve(x jsonb,e jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare t text:=e->>'team';enemy text:=public._r_other(t);u jsonb:=public._r_unit(x->'s',t,e->>'uid');v jsonb;g jsonb;team text;ids jsonb;op text:=e->>'op';selected text:=e->>'selection';r jsonb;owner_id text:=e->>'owner';list jsonb;vals jsonb;item jsonb;i integer;delta numeric;
begin
 if not public._r_enabled(x,e) then return x;end if;
 x:=jsonb_set(x,'{s,remakeSource}',to_jsonb(t),true);
 if op='remake' then x:=public._x_resolve(x,e);
 elsif op='destroy_two' then
  select coalesce(jsonb_agg(q->'uid'),'[]') into ids from (select value q from jsonb_array_elements(x#>array['s',enemy,'field']) where not public._x_block(x->'s',enemy,value,t,'destroy') order by random() limit 2) eligible;
  x:=public._r_visual(x,'lightning',enemy,ids);x:=public._r_destroy(x,enemy,ids);
 elsif op='hunt_monsters' then
  foreach team in array array[t,enemy] loop
   select coalesce(jsonb_agg(q->'uid'),'[]') into ids from (select value q from jsonb_array_elements(x#>array['s',team,'field']) where (public._r_card(public._r_identity(value))->'tags') ? 'monstro' and not public._x_block(x->'s',team,value,t,'destroy') order by public._r_power(x->'s',team,value) desc limit 2) eligible;
   x:=public._r_visual(x,'arrows',team,ids);x:=public._r_destroy(x,team,ids);
  end loop;
 elsif op='shuffle_lane' then
  list:='[]';foreach team in array array[t,enemy] loop for v in select value from jsonb_array_elements(x#>array['s',team,'field']) where value->>'lane'=selected and not public._r_protect(x->'s',team,(value->>'lane')::integer,t) loop list:=list||jsonb_build_array(jsonb_build_object('team',team,'uid',v->>'uid','power',public._r_power(x->'s',team,v)));end loop;end loop;
  select coalesce(jsonb_agg(value->'power' order by random()),'[]') into vals from jsonb_array_elements(list);
  for item,i in select value,ordinality::integer-1 from jsonb_array_elements(list) with ordinality loop team:=item->>'team';v:=public._r_unit(x->'s',team,item->>'uid');delta:=(vals->>i)::numeric-(item->>'power')::numeric;if delta>=0 or not public._x_block(x->'s',team,v,t,'reduce') then v:=v||jsonb_build_object('powerShift',coalesce((v->>'powerShift')::numeric,0)+delta);x:=public._r_set_unit(x,team,v->>'uid',v);end if;end loop;
 elsif op='anubis' and public._x_block(x->'s',enemy,public._r_unit(x->'s',enemy,selected),t,'destroy') then null;
 elsif op='steal' and public._x_block(x->'s',enemy,public._r_unit(x->'s',enemy,selected),t,'steal') then null;
 elsif op='steal_hand' and not exists(select 1 from jsonb_each(x->'r') where value->>'team'=enemy and (jsonb_array_length(coalesce(value->'hand','[]'))>0 or jsonb_array_length(coalesce(value->'deck','[]'))>0)) then
  select value into g from jsonb_array_elements(x#>array['s',enemy,'grave']) where public._r_card(value->>'cardId')<>'{}' and not coalesce((public._r_card(value->>'cardId')->>'specialOnly')::boolean,false) and public._x_grave_ok(x,e,value,false) order by random() limit 1;
  if g is not null then x:=jsonb_set(x,array['s',enemy,'grave'],coalesce((select jsonb_agg(value order by ordinality) from jsonb_array_elements(x#>array['s',enemy,'grave']) with ordinality a(value,ordinality) where value->>'uid'<>g->>'uid'),'[]'),true);x:=public._r_grave_sync(x,enemy);x:=jsonb_set(x,array['r',owner_id,'hand'],(x#>array['r',owner_id,'hand'])||jsonb_build_array(g->'cardId'),true);end if;
 else x:=public._r_resolve_before_remake(x,e);
 end if;if op='equip' then v:=public._r_unit(x->'s',t,selected);if v is not null then v:=v||jsonb_build_object('equipmentOwners',coalesce(v->'equipmentOwners','{}')||jsonb_build_object(e->>'cardId',owner_id),'mutedEquipment',coalesce(v->'mutedEquipment','[]')-(e->>'cardId'));x:=public._r_set_unit(x,t,selected,v);end if;end if;return public._r_reconcile(x)#-'{s,remakeSource}';
end $$;

-- A timed-out opponent choice cannot hold the original turn indefinitely.
do $action_backup$
declare d text;
begin if to_regprocedure('public._r_action_before_remake(jsonb,jsonb,text,jsonb)') is null then d:=pg_get_functiondef('public._r_action(jsonb,jsonb,text,jsonb)'::regprocedure);d:=replace(d,'FUNCTION public._r_action(','FUNCTION public._r_action_before_remake(');execute d;end if;end $action_backup$;
create or replace function public._r_action(s jsonb,resources jsonb,actor text,a jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare x jsonb;p jsonb:=s->'pendingEffect';e jsonb;
begin
 if a->>'type'='skip_turn' and p->>'actor' is distinct from actor and p->>'expiresAt' is not null and (p->>'expiresAt')::timestamptz<=clock_timestamp() then
  x:=public._r_init(s,resources);e:=(p->'event')||jsonb_build_object('selection',p#>>'{options,0,value}');x:=x#-'{s,pendingEffect}';x:=jsonb_set(x,'{s,effectQueue}',jsonb_build_array(e)||coalesce(x#>'{s,effectQueue}','[]'),true);x:=public._r_drain(x,true);x:=x#-'{s,abilityPhase}';x:=jsonb_set(x,array['r',actor,'skipNextTurn'],'false'::jsonb,true);return jsonb_set(x,array['r',actor,'playedThisTurn'],'true'::jsonb,true);
 end if;return public._r_action_before_remake(s,resources,actor,a);
end $$;
do $choice_deadline$
declare d text;a text;b text;
begin d:=pg_get_functiondef('public._r_drain(jsonb,boolean)'::regprocedure);
 a:='x:=jsonb_set(x,''{s,pendingEffect}'',pending,true);';b:='pending:=pending||jsonb_build_object(''expiresAt'',clock_timestamp()+interval ''30 seconds'');'||a;
 if position(b in d)=0 then d:=replace(d,a,b);execute d;end if;
end $choice_deadline$;

-- A lock on one unit disables its own ability, not its equipment or allied auras.
-- Dionysus continues to suspend all effects according to the approved rules.
create or replace function public._r_shield(s jsonb,t text,l integer) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from jsonb_array_elements(coalesce(s#>array[t,'field'],'[]')) v where coalesce((v->>'lane')::integer,0)=l and public._r_id(v)='heimdall' and coalesce((v->>'silencedJogadas')::integer,0)=0 and not coalesce((v->>'silencedOwnerEnd')::boolean,false) and (public._r_live(s) or s->>'silenceTeam'=public._r_other(t) or coalesce(v->>'silenceExemptStamp'=s->>'silenceStartedBy',false))) $$;
create or replace function public._x_global(s jsonb,t text,u jsonb) returns boolean language sql stable set search_path='' as $$
 select public._r_live(s) or coalesce(u->>'silenceExemptStamp'=s->>'silenceStartedBy',false) or coalesce(s->>'silenceTeam'=public._r_other(t) and public._r_shield(s,t,coalesce((u->>'lane')::integer,0)),false) $$;
create or replace function public._r_active(s jsonb,t text,u jsonb) returns boolean language sql stable set search_path='' as $$
 select public._x_global(s,t,u) and coalesce((u->>'silencedJogadas')::integer,0)=0 and not coalesce((u->>'silencedOwnerEnd')::boolean,false) $$;
do $personal_power$
declare d text;clause text;
begin
 d:=pg_get_functiondef('public._r_power(jsonb,text,jsonb,integer)'::regprocedure);
 d:=replace(d,'if not public._r_active(s,t,u) then return','if not public._x_global(s,t,u) then return');
 foreach clause in array array['if id=''lukyan'' and','if id in (''soldado-esparta'',''guardiao-nordico'') then','if id=''lobo-alfa'' then','if id=''lobo-omega'' and','if id in (''mulher'',''homem'') then','if id=''lukyan-rei-de-todos'' then'] loop
  if position('if public._r_active(s,t,u) and '||substring(clause from 4) in d)=0 then d:=replace(d,clause,'if public._r_active(s,t,u) and '||substring(clause from 4));end if;
 end loop;execute d;
 d:=pg_get_functiondef('public._r_options_before_remake(jsonb,jsonb)'::regprocedure);d:=replace(d,'public._r_active(x->''s'',t,candidate)','public._x_global(x->''s'',t,candidate)');execute d;
end $personal_power$;

-- Achilles' entry bonus belongs to the row in which it was earned.
do $achilles_backup$
declare d text;
begin
 if to_regprocedure('public._r_reconcile_before_remake(jsonb)') is null then d:=pg_get_functiondef('public._r_reconcile(jsonb)'::regprocedure);d:=replace(d,'FUNCTION public._r_reconcile(','FUNCTION public._r_reconcile_before_remake(');execute d;end if;
 d:=pg_get_functiondef('public._r_reconcile_before_remake(jsonb)'::regprocedure);d:=replace(d,'enabled:=public._r_active(x->''s'',t,u);','enabled:=public._x_global(x->''s'',t,u);');execute d;
 d:=replace(d,'if exists(select 1 from jsonb_array_elements(x#>array[''s'',t,''field'']) v where v->>''uid''<>u->>''uid'' and v->>''lane''=u->>''lane'') then u:=u||jsonb_build_object(''bonus''','if public._r_active(x->''s'',t,u) and exists(select 1 from jsonb_array_elements(x#>array[''s'',t,''field'']) v where v->>''uid''<>u->>''uid'' and v->>''lane''=u->>''lane'') then u:=u||jsonb_build_object(''bonus''');execute d;
 d:=pg_get_functiondef('public._r_resolve_before_remake(jsonb,jsonb)'::regprocedure);
 if position('greekBonusLane' in d)=0 then
  d:=replace(d,'x:=public._r_change(x,t,u->>''uid'',t,n);','x:=public._r_change(x,t,u->>''uid'',t,n);v:=public._r_unit(x->''s'',t,u->>''uid'');if v is not null then x:=public._r_set_unit(x,t,v->>''uid'',v||jsonb_build_object(''greekBonusLane'',lane,''greekBonusTeam'',t,''greekBonusAmount'',n));end if;');execute d;
 end if;
end $achilles_backup$;
create or replace function public._r_reconcile(x jsonb) returns jsonb language plpgsql volatile set search_path='' as $$
declare t text;u jsonb;
begin
 foreach t in array array['player_one','player_two'] loop for u in select value from jsonb_array_elements(coalesce(x#>array['s',t,'field'],'[]')) where value ? 'greekBonusLane' loop
  if u->>'greekBonusLane' is distinct from u->>'lane' or u->>'greekBonusTeam' is distinct from t then u:=(u||jsonb_build_object('bonus',coalesce((u->>'bonus')::numeric,0)-coalesce((u->>'greekBonusAmount')::numeric,0)))-'greekBonusLane'-'greekBonusTeam'-'greekBonusAmount';x:=public._r_set_unit(x,t,u->>'uid',u);end if;
 end loop;end loop;return public._r_reconcile_before_remake(x);
end $$;

-- Once-per-Round abilities keep their spent state through resurrection.
create or replace function public._x_memory(s jsonb,u jsonb,g jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare k text;
begin if g->>'rebornRound'=s->>'round' then foreach k in array array['rebornOnce','savedOnce','mourningUsed'] loop if coalesce((g->>k)::boolean,false) then u:=u||jsonb_build_object(k,true);end if;end loop;end if;return u;end $$;
do $revive_memory$
declare d text;a text;b text;
begin
 d:=pg_get_functiondef('public._r_resolve_before_remake(jsonb,jsonb)'::regprocedure);
 a:='x:=public._r_spawn(x,cid,t,owner_id,lane,coalesce((g->>''progress'')::integer,0));';
 b:=a||'/* round_memory_v40 */ select value into v from jsonb_array_elements(x#>array[''s'',t,''field'']) with ordinality a(value,ordinality) where value->>''cardId''=cid and value->>''playedBy''=owner_id order by ordinality desc limit 1;if v is not null then x:=public._r_set_unit(x,t,v->>''uid'',public._x_memory(x->''s'',v,g));end if;';
 if position('round_memory_v40' in d)=0 then d:=replace(d,a,b);execute d;end if;
end $revive_memory$;

-- Restrict helper functions to the authoritative engine.
do $acl$ declare f record;begin for f in select p.oid::regprocedure r from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (left(p.proname,3)='_x_' or p.proname like '%_before_remake') loop execute 'revoke all on function '||f.r||' from public,anon,authenticated';end loop;end $acl$;
notify pgrst,'reload schema';
commit;
